-- 2. DATA ENTRI
INSERT INTO entri (id, term, definition, sumber_id) VALUES 
(1, 'apêg', 'a pêg : 1. zva. a pêk , G. — 2. ng , of ngêpêg , vochtig inpakken, ineenrollen of opleggen, bv. tabak, om te maken, dat de reuk en kracht sterker wordt JR., vgl. a pêk . Javaansch-Nederlandsch Handwoordenboek, Gericke en Roorda, 1901, #918.', 9),
(2, 'adhak', 'a dhak : zelden gebr. Waj. II, 272; GB. X, 301 (vrg. pêdhak ). — a dhakan , KN. a dhakya , dhakya , en a dhake , KW. dicht bij de hand, voor de hand liggend DN. I,
540. Vgl. jolok , jujugan . a dhakan , wangs. voor capaka , [ cêpakan ] JZ. II, ... selengkapnya a dhak : zelden gebr. Waj. II, 272; GB. X, 301 (vrg. pêdhak ). — a dhakan , KN. a dhakya , dhakya , en a dhake , KW. dicht bij de hand, voor de hand liggend DN. I, 540. Vgl. jolok , jujugan . a dhakan , wangs. voor capaka , [ cêpakan ] JZ. II, 267. — ngya , KW. zva. nyêdhak . Wk. Javaansch-Nederlandsch Handwoordenboek, Gericke en Roorda, 1901, #918.', 9),
(3, 'amêr', 'a mêr : KW. zva. a rih , KS. 128 (vrg. imêr ). — ng , mangamêr , zva. ngarih- a rih . Zie ook Wk. en W. ngamêr , KN. gelukkig, voorspoedig, vlot gaan Wk. — pangamêr , subst. den. JZ. II. Javaansch-Nederlandsch Handwoordenboek, Gericke en Roorda, 1901, #918.', 6),
(4, 'amil', 'a mil : ( A rab.[ A rab]) dorpsgeestelijke of ondergeschikt geestelijke in de groote moskeeën v. d. B. 54. Zie ook ZG. XVIII, 8 en ER. III, 224, 225, 264. Javaansch-Nederlandsch Handwoordenboek, Gericke en Roorda, 1901, #918.', 1),
(5, 'ambartala', 'a mbartala : KW. zva. a ra- a ra , Wk. Javaansch-Nederlandsch Handwoordenboek, Gericke en Roorda, 1901, #918.', 5),
(6, 'ăngja', 'ă ngja : KW. zva. ă nja- ă nja . — ng , zva. a njêmpalik , Wk. Javaansch-Nederlandsch Handwoordenboek, Gericke en Roorda, 1901, #918.', 1),
(7, 'anggah', 'a nggah : en a nggêh , WS. 162 KW. zva. a ngkah ( a rah ) kukuh , en karêp . a nggêh , ook zva. a nggêp , pêthuk , prênah , JZ. I; WS. 162. — ng , zva. ngarah , Wk. vgl. panggah . — panganggêh , zva. panganggêp . — ... selengkapnya a nggah : en a nggêh , WS. 162 KW. zva. a ngkah ( a rah ) kukuh , en karêp . a nggêh , ook zva. a nggêp , pêthuk , prênah , JZ. I; WS. 162. — nganggah , zva. ngarah , Wk. vgl. panggah . — panganggêh , zva. panganggêp . — manganggêh , en nganggêh , zva. mêthuk , vgl. panggêh . Javaansch-Nederlandsch Handwoordenboek, Gericke en Roorda, 1901, #918.', 2),
(8, 'ngalèn-alèni', 'ngalèn- a lèni : zie a li- a li . Javaansch-Nederlandsch Handwoordenboek, Gericke en Roorda, 1901, #918.', 1),
(9, 'ahat', 'a hat [BV.] : vlg. Juynb. in Bijdr. 5e R. X, 180 A rab [ A rab], zucht over hetgeen men ontbeert. Javaansch-Nederlandsch Handwoordenboek, Gericke en Roorda, 1901, #918.', 4),
(10, 'akik', 'a kik [BV.] : A rab. [ A rab] Juynb. in Bijdr. 5e R. X, 192. Javaansch-Nederlandsch Handwoordenboek, Gericke en Roorda, 1901, #918.', 10),
(11, 'ayo', 'a yo [BV.] : zie nog WG. 97, 103. — a yon , ''t met elkander eens zijn, en a yon- a yonan , meṭ elkander wedijveren TS. 71. Javaansch-Nederlandsch Handwoordenboek, Gericke en Roorda, 1901, #918.', 10),
(12, 'ācāmaniya', 'ā cāmaniya : S. a ir untuk kumur; a ir pencuci muka. Kawi - Indonesia, Wojowasito, 1977, #1019.', 9),
(13, 'ādityakuṇḍala', 'ā dityakuṇḍala : S. lingkaran matahari; a nting- a nting yang ujudnya seperti lingkaran dan sangat berkilau-kilauan. Kawi - Indonesia, Wojowasito, 1977, #1019.', 2),
(14, 'agni', 'a gni : S. a pi; dewa a pi. Kawi - Indonesia, Wojowasito, 1977, #1019.', 7),
(15, 'akěn', 'a kěn : I. seperti; sebagai; seolah-olah; → a ngkěn ; II. a khiran; dalam bahasa Indonesia sama dengan a khiran -kan a tau -i. Kawi - Indonesia, Wojowasito, 1977, #1019.', 5),
(16, 'akṣamā', 'a kṣamā : S. kṣamā sabar; maaf; a mpun; a ngakṣama memaafkan; inkěn diberi maaf; diberi izin; pangakṣama maaf; a mpun; izin. Kawi - Indonesia, Wojowasito, 1977, #1019.', 6),
(17, 'ama', 'a ma : S. I. baik; bagus; II. a yah; r a yah. Kawi - Indonesia, Wojowasito, 1977, #1019.', 2),
(18, 'anala', 'a nala : S. a pi; dewa a pi. Kawi - Indonesia, Wojowasito, 1977, #1019.', 6),
(19, 'antakāgni', 'a ntakāgni : S. a pi maut; a pi kematian. Kawi - Indonesia, Wojowasito, 1977, #1019.', 1),
(20, 'akasa', 'a kasa (akOsO) : kasa: langit, a wang- a wang. Kawi - Jarwa, Dirjasupraba, 1931, #1263.', 9),
(21, 'antarala', 'a ntarala (antOrOlO) : a wang- a wang. Kawi - Jarwa, Dirjasupraba, 1931, #1263.', 4),
(22, 'ambara', 'a mbara (ambOrO) : uluk, a wang- a wang, lêlana, nguja. Têmbung Kawi Mawi Têgêsipun, Wintêr, 1928, #1506.', 5),
(23, 'agrêng', 'a grêng (agr|G) : a las [x]: a las gêdhe. Kawi - Jarwa, Poerwadarminta, 1943, #1856.', 2),
(24, 'aba', 'a ba : 1 signal, command. 2 to order ( a t a certain price). A ku mau [x] bakmi gorèng. I ordered fried noodles. Ora susah takon rêgane, têrus [x] wae. You don''t need to a sk the price, just order so-much-money''s worth. 3 spoken word; to say, speak. [x]-ne judging by the sound. [x]-n-[x]-n rg loud noise. ... selengkapnya a ba : 1 signal, command. 2 to order ( a t a certain price). A ku mau [x] bakmi gorèng. I ordered fried noodles. Ora susah takon rêgane, têrus [x] wae. You don''t need to a sk the price, just order so-much-money''s worth. 3 spoken word; to say, speak. [x]-ne judging by the sound. [x]-n-[x]-n rg loud noise. ng/di-[x]-ni 1 to give a signal/command to. 2 to quote [ a price]. A ku di-[x]-ni pira sewane. She told me how much the rent was. Javanese-English Dictionary, Horne, 1974, #1968.', 5),
(25, 'aboge', 'a boge : first day in the A lip windu (shc from A LIP RÊBO WAGE), used a s the basis for calculating the date on which Lebaran will fall in a ny given year. Javanese-English Dictionary, Horne, 1974, #1968.', 7),
(26, 'ajah', 'a jah : [x]- a n ( a ) trained ( a nimal). Ge a na ing sirkus iki kabèh [x]- a n. The elephants in this circus a re a ll performing elephants. ng/di-[x]- a ke to train for smn; to have trained. A ng-[x]- a ke a sune. A had his dog trained. ng/di-[x]-(i) to train [ a nimals]. Javanese-English Dictionary, Horne, 1974, #1968.', 2),
(27, 'aga', 'a ga : rg var of SAGA. [x]-n that which is saved or laid a side. ø/di-[x] to save up, lay a side. Dhuwite di-[x] kanggo tuku omah mbesuk. He''s saving up for a house. Javanese-English Dictionary, Horne, 1974, #1968.', 3),
(28, 'ahli', 'a hli : specialist, expert. dhoktêr [x] urat saraf neurologist. dhoktêr [x]pênyakit kulit dermatologist. wong [x] budi a person of intelligence. ke-[x]- a n expertise, specialized knowledge. ng/di-[x]-kake to convey expert knowledge to, to train a s a n expert. [x] waris heir. Javanese-English Dictionary, Horne, 1974, #1968.', 6),
(29, 'aliyas', 'a liyas : or; a lso known a s. gaweyan manca, [x] barang import foreign-made things, a lso called imported goods. Javanese-English Dictionary, Horne, 1974, #1968.', 6),
(30, 'ambyak', 'a mbyak : [x]-[x]- a n to move in great numbers. Wong-wong padha mulih [x]-[x]- a n. People thronged homeward. Javanese-English Dictionary, Horne, 1974, #1968.', 10),
(31, 'ambus', 'a mbus : ng/di-[x] to sniff ( a t). Teronge di-[x]-[x] Kancil. Mouse-Deer kept sniffing a t the eggplant. Javanese-English Dictionary, Horne, 1974, #1968.', 3),
(32, 'acan', 'a can : rg a t a ll, a ltogether. ora [x] not a t a ll. Javanese-English Dictionary, Horne, 1974, #1968.', 4),
(33, 'acêng', 'a cêng : [x]- a n lustful, lascivious. ng-[x] to have a n erection. Javanese-English Dictionary, Horne, 1974, #1968.', 2),
(34, 'lail(l)ah(a)', 'lail(l) a h( a ) : 1 there is no God but A llah. 2 excl of dismay, despair. [x] hail(l)olahu there is no God but A llah. Javanese-English Dictionary, Horne, 1974, #1968.', 8),
(35, 'acaram', 'a caram [Ind] : a li- a li paningkah. Bausastra Indonesia-Jawi, Purwadarminta, c. 1939, #1979.', 9),
(36, 'ahkam', 'a hkam [Ind] : a nggêr- a nggêr. Bausastra Indonesia-Jawi, Purwadarminta, c. 1939, #1979.', 7),
(37, 'ajujah,ajujat', 'a jujah, a jujat [Ind] : ngala- a la, nyatur a la. Bausastra Indonesia-Jawi, Purwadarminta, c. 1939, #1979.', 2),
(38, 'amanat', 'a manat [Ind] : 1 kaslamêtan, katêntrêman; 2 a pa- a pa kang dititipake (dianggo tanggungan, dianggo cêkêlan, dipracayakake) 3 piwêling, piwêkas; dikan: dipracayakake, dipasrahake. Bausastra Indonesia-Jawi, Purwadarminta, c. 1939, #1979.', 9),
(39, 'anak rambut', 'a nak rambut [Ind] : a thi- a thi, sinom. Bausastra Indonesia-Jawi, Purwadarminta, c. 1939, #1979.', 1),
(40, 'angkasa', 'a ngkasa [Ind] : a wang- a wang. Bausastra Indonesia-Jawi, Purwadarminta, c. 1939, #1979.', 10),
(41, 'awang-awang(an),awang gemawang', 'a wang- a wang( a n), a wang gemawang [Ind] : a wang- a wang. Bausastra Indonesia-Jawi, Purwadarminta, c. 1939, #1979.', 4),
(42, 'anduk', 'a nduk : Kw. a pprocher, s'' a pprocher. Dictionnaire Javanais-Français, L''Abbé P. Favre, 1870, #917.', 9),
(43, 'arungan', 'a rungan : N.K. a voir beaucoup à faire, a voir à lutter contre des difficultés. Dictionnaire Javanais-Français, L''Abbé P. Favre, 1870, #917.', 9),
(44, 'awag', 'a wag : N.K. ng , superficiel, sans fondement, imprévu. a wagan , conjecture, soupçon, supposition. iku mung a wagan bae , cela n''est qu''une conjecture. Dictionnaire Javanais-Français, L''Abbé P. Favre, 1870, #917.', 2),
(45, 'april', 'a pril : a vril, le mois d'' a vril. Dictionnaire Javanais-Français, L''Abbé P. Favre, 1870, #917.', 8),
(46, 'apêm', 'a pêm : N.K. espèce de galette faite a vec de la farine de riz. ng , frapper a vec le poing sur le visage. Dictionnaire Javanais-Français, L''Abbé P. Favre, 1870, #917.', 10),
(47, 'ambar', 'a mbar : N.K. a mbre, de l'' a mbre. Dictionnaire Javanais-Français, L''Abbé P. Favre, 1870, #917.', 7),
(48, 'agustus', 'a gustus : a oût, le mois d'' a oût. Dictionnaire Javanais-Français, L''Abbé P. Favre, 1870, #917.', 10),
(49, 'abdas', 'a bdas : la purification qui se fait a vant la prière (chez les Mahométans): l''eau qui sert à la purification, a vant la prière. Dictionnaire Javanais-Français, L''Abbé P. Favre, 1870, #917.', 10),
(50, 'ancit', 'a ncit (ancIt) : [oncat- a ncit]: manguntit; [ngoncat- a ncitake]: huntitake, nuntitake. Bausastra: Jarwa Kawi, Padmasusastra, 1903, #11.', 5),
(51, 'andaru', 'a ndaru () : a ndaru, hadaru, darus, wilaba. Bausastra: Jarwa Kawi, Padmasusastra, 1903, #11.', 1),
(52, 'andik', 'a ndik (andI?) : a ndik. Bausastra: Jarwa Kawi, Padmasusastra, 1903, #11.', 8),
(53, 'ănta', 'ă nta (OntO) : [pang- ă nta]: hutpana. Bausastra: Jarwa Kawi, Padmasusastra, 1903, #11.', 8),
(54, 'arak', 'a rak (ara?) : a rak, twak, tyak, sajêng, waragang. Bausastra: Jarwa Kawi, Padmasusastra, 1903, #11.', 7),
(55, 'akal bakal', 'a kal bakal () : pra(of par)wita; [ a kal bakal nagara]: witarêdya. Bausastra: Jarwa Kawi, Padmasusastra, 1903, #11.', 7),
(56, 'adil', 'a dil (adIl) : niti, sidya-sidana; [ngi]: manidyasani, ngrajaniti; [luwih a dil]: a mbahudhêndha; [panggêdhening pangadilan]: prawara, mahasidyana. Bausastra: Jarwa Kawi, Padmasusastra, 1903, #11.', 7),
(57, 'asar', 'a sar () : [wayah a sar]: tibralayu. Bausastra: Jarwa Kawi, Padmasusastra, 1903, #11.', 5),
(58, 'asik', 'a sik (asI?) : [osak- a sik]: umalisak, julik, malisak. Bausastra: Jarwa Kawi, Padmasusastra, 1903, #11.', 7),
(59, 'asmara', 'a smara (asmOrO) : onêng, hyun, hayun, nang, rimang, mangê; [kn]: hanang, hunang of honang, hakung, katuridan, sêmaranala, sêmaratura, branta of brăngta; [ulah a smara]: mangê. Bausastra: Jarwa Kawi, Padmasusastra, 1903, #11.', 6),
(60, 'awit', 'a wit (awIt) : krana of karana, tapan, tapya, sning, lila, pan, yyrawan, mapan, nguni-uni; [ngawit]: ngawat; [ngawiti]: ngawati; [kawitan]: kamulan; [sakawit]: sapurwa of sapurbya; [miwiti]: mungari; [ a wit saka]: witya. Bausastra: Jarwa Kawi, Padmasusastra, 1903, #11.', 6),
(61, 'alih', 'a lih (alIh) : a lih; [ng]: halèh, mapindhah; [pangalih]: pamindhah; [pangalihan]: sadeya. Bausastra: Jarwa Kawi, Padmasusastra, 1903, #11.', 7),
(62, 'alon', 'a lon (alOn) : riri, ririh, rêrêh, rarat, rumini, lon, manda of mănda, ngaris; [ a lon- a lonan]: rarat-raratan, mariri-riri; [ngêlon-êloni]: ngloni. Bausastra: Jarwa Kawi, Padmasusastra, 1903, #11.', 2),
(63, 'alad', 'a lad () : [ngalad- a lad]: humalad, malad. Bausastra: Jarwa Kawi, Padmasusastra, 1903, #11.', 7),
(64, 'adhêp', 'a dhêp (aD|p) : a rêp, madahab; [ a dhêp- a dhêpan]: pandêlyan; [ng]: umarêk, marêk, mayogapti, mayogabyantara; [ngadhêpi]: umarêki, marêki; [ngadhêpake]: ngadhêpkên; [pangadhêp]: pamante; [pangadhêpan]: pamanteyan; [madhêp]: umarêp, marêp, maptya. Bausastra: Jarwa Kawi, Padmasusastra, 1903, #11.', 10),
(65, 'adhêm', 'a dhêm (aD|m) : a tis, a dhêm, nyênnyêt, marta, mêrta, mrêtta, matis; [ngi]: paramarta, paramêrta, paramrêta, martani, madhêmi; [pangadhêm]: panawa, panyêp. Bausastra: Jarwa Kawi, Padmasusastra, 1903, #11.', 9),
(66, 'aju', 'a ju () : a ju, a ngsah, a ngsya; [ngajoni]: majêngi, ngangsahi; [ngajokake]: majêngkên, ngangsahkên; [paju]: pado; [maju]: umara, a ngsah, nangsah, nangsêh, mara, maraya, maju, majêng, mabyantara, ngangsêh, ngangsya. Bausastra: Jarwa Kawi, Padmasusastra, 1903, #11.', 2),
(67, 'alo', 'a lo () : A lo, suwawi, payo, mah, mara, maryan, mapapa. Bausastra: Jarwa Kawi, Padmasusastra, 1903, #11.', 7),
(68, 'amit', 'a mit (amIt) : [p]: A mit, sajar, pamwit, muhun, mwit; [pamitan]: mumuhun. Bausastra: Jarwa Kawi, Padmasusastra, 1903, #11.', 8),
(69, 'ămba', 'ă mba (OmbO) : a sis, tara, têlar, sis, sêlar, wir, wira of wera, wirrya, wirya, wi-rya, wiraya, wêlar, wyara, wiyara, wyat, wiyat, waryya, leswa, lwa, lwah, lwan, pramu of pramo, paramu of paramo, pramu(of paramu)sita, pramu(of paramu)sesa; [ a mbaning a ti]: pramusitaya; [ngambani]: ngawera; [ngambakake]: ... selengkapnya ă mba (OmbO) : a sis, tara, têlar, sis, sêlar, wir, wira of wera, wirrya, wirya, wi-rya, wiraya, wêlar, wyara, wiyara, wyat, wiyat, waryya, leswa, lwa, lwah, lwan, pramu of pramo, paramu of paramo, pramu(of paramu)sita, pramu(of paramu)sesa; [ a mbaning a ti]: pramusitaya; [ngambani]: ngawera; [ngambakake]: ngawerakên; [kamban]: kaweran; [saambane]: panghamban; [luwih ă mba]: pramu(of paramu)dita, pramu(of paramu)ditaya. Bausastra: Jarwa Kawi, Padmasusastra, 1903, #11.', 6),
(70, 'ambah', 'a mbah () : ura, uran, cacad, tampak, srambah; [ a mbah- a mbahan]: huran-huran; [ngambah]: umambah, a mbêh; [ngambah]: nacak, napak, nampak, nambah, tampak, tumampak, sumarambah, la(of lê)lana, mai, mahi, manambah, muwwah, mangura, ngura, ngamah; [pangambah]: panapak, panambah; [kambah]: nidu, kambêh. Bausastra: Jarwa Kawi, Padmasusastra, 1903, #11.', 9),
(71, 'ămbra', 'ă mbra (OmbrO) : [ng- ă mbra]: luluya. Bausastra: Jarwa Kawi, Padmasusastra, 1903, #11.', 10),
(72, 'ambêk', 'a mbêk (amb|k) : [ a mbêkan]: U(of O)swasa =, u(of o)swasa, U(of O)syasa =, u(of o)syasa, nilangga, swasa, syasa, wayuwita, wayuwiya; [ a mbêk wantêr]: bawisyati. Bausastra: Jarwa Kawi, Padmasusastra, 1903, #11.', 4),
(73, 'ambal', 'a mbal () : [ a mbal- a mbalan]: masanggaruwan; [kaambalan]: kaban. Bausastra: Jarwa Kawi, Padmasusastra, 1903, #11.', 7),
(74, 'agak', 'a gak (aga?) : [ng- a gak]: mangantak- a ntak, mangêntak-êntak. Bausastra: Jarwa Kawi, Padmasusastra, 1903, #11.', 6),
(75, 'agal', 'a gal () : kramu, maakas, ganal; [luwih a gal]: sugal. Bausastra: Jarwa Kawi, Padmasusastra, 1903, #11.', 5),
(76, 'agama', 'a gama (agOmO) : gama; [parentahing a gama]: panat. Bausastra: Jarwa Kawi, Padmasusastra, 1903, #11.', 4),
(77, 'obatangêt', 'obat a ngêt (obat aG|t) : wêdhak a ngêt. Bausastra: Jarwa Kawi, Padmasusastra, 1903, #11.', 5),
(78, 'angkat', 'a ngkat (aGkat) : A ngkat, nyat, tua, war; [ng]: a nyat, nyat, midhang, nganjat; [pangkat]: A (of a )ndha, rambah, tundha, sundha, wija, wijang, pana, parah, jat, bilik; [pangkatan]: rambahan, pataran]: of patarran; [pangkat-pangkat]: parah-parah; [mangkat]: hyangkat, u(of nu)mangkat, tumiang, tumundha, sumunda, ... selengkapnya a ngkat (aGkat) : A ngkat, nyat, tua, war; [ngangkat]: a nyat, nyat, midhang, nganjat; [pangkat]: A (of a )ndha, rambah, tundha, sundha, wija, wijang, pana, parah, jat, bilik; [pangkatan]: rambahan, pataran]: of patarran; [pangkat-pangkat]: parah-parah; [mangkat]: hyangkat, u(of nu)mangkat, tumiang, tumundha, sumunda, yyrakat, marah, musung. Bausastra: Jarwa Kawi, Padmasusastra, 1903, #11.', 2),
(79, 'angèl', 'a ngèl (aGEl) : iwêh, A ngèl, rungsit, sirung, mèwuh, ngèl, ngela; [ngake]: a nglih, a nglong, nita, kaiyalan, panglih, ngèl, nglih of ngêlih. Bausastra: Jarwa Kawi, Padmasusastra, 1903, #11.', 5),
(80, 'agêr', 'a gêr (ag|r) : hyrubi, pratita, tagya; [panganggêr- a nggêr]: patagya-tagyana; [ a gêr a rêp]: hyrubi mahyun; [layang hanggêr]: pratitasastra, pratyawilapa; [planggêran]: a ogêm. Bausastra: Jarwa Kawi, Padmasusastra, 1903, #11.', 8),
(81, 'anggit', 'a nggit (aGgIt) : ikêt, itung, rèh, reka, rumpaka, kupita, sawung, suji, pindha, gita, gupit, gupita, gubah, thika; [ a nggitan]: gubahan; [ng]: itung, umikêt, a nggupita, nênun, nawung, rumancana, rumpaka, rumampaka, sumuji, manawung, manulad, mindha, marna, mursita, mikêt, garêmêki, ngrancani, ngrante, ngracana, ... selengkapnya a nggit (aGgIt) : ikêt, itung, rèh, reka, rumpaka, kupita, sawung, suji, pindha, gita, gupit, gupita, gubah, thika; [ a nggitan]: gubahan; [nganggit]: itung, umikêt, a nggupita, nênun, nawung, rumancana, rumpaka, rumampaka, sumuji, manawung, manulad, mindha, marna, mursita, mikêt, garêmêki, ngrancani, ngrante, ngracana, ngrumpaka, ngrampêki, ngikêt, ngapus; [nganggit kêmbang]: nyuji; [nganggit- a nggit]: ngapus- a pus; [panganggit]: panawung, pratali, pangripta, pangikêt, pangapus. Bausastra: Jarwa Kawi, Padmasusastra, 1903, #11.', 2),
(82, 'anak', 'a nak (ana?) : a nak a nung a nindita, P.W., 213-3 v. o. a nung Kw. = kuwasa, nindita = linuwih. Têmbung Bêcik, Padmasusastra, 1898, #13.', 7),
(83, 'aran', 'a ran () : a . sinung a ran a wasta ... P. 74-2.| b. pan ingsun iki pêpatih, ranku ring rat Lêmbusura, H.S. 95 p. 9. Têmbung Bêcik, Padmasusastra, 1898, #13.', 8),
(84, 'adat', 'a dat () : kayêktosan kawon dening a dat, J. Z. I. 206-1, zie lumrah. Têmbung Bêcik, Padmasusastra, 1898, #13.', 9),
(85, 'ala', 'a la (OlO) : en sirna | A la sirnane tinampik, H. S 191 p. 14 P. L. I, 183-3 v. o. Têmbung Bêcik, Padmasusastra, 1898, #13.', 5),
(86, 'ajal', 'a jal () : KN. | Sang nata a ndangu a jal kamulanira. P.76-4. Têmbung Bêcik, Padmasusastra, 1898, #13.', 2),
(87, 'ayam', 'a yam () : KN. prawirane wutuh a yam, Rm. 423-10. Têmbung Bêcik, Padmasusastra, 1898, #13.', 7),
(88, 'angganararas', 'a ngganararas (aGgOnOraras) : Sanadyan kathah titahing dewa, kang kasăngga ing pratiwi kongkulan ing ngakasa, kapit ing samudra, kathah kang a ngganararas, P. I, 1-9 v. o. Têmbung Bêcik, Padmasusastra, 1898, #13.', 7),
(89, 'anggung gawe', 'a nggung gawe (aGgUG gawe) : = pijêr | a nuntun gawe dêlanggung, a nggung gawe pagêr bojod, Kantj. 164 (49). Têmbung Bêcik, Padmasusastra, 1898, #13.', 8),
(90, 'tapakangin', 'tapak a ngin (tapa? aGIn) : kopat-kapita kaya ula tapak a ngin, P. II, 287-9 zie branjangan. Têmbung Bêcik, Padmasusastra, 1898, #13.', 6),
(91, 'antariksa', 'a ntariksa (antarIksO) : of ă ntariksa, Kw. het uitspansel [Skr. a ntarixa]. ngăntariksa, in de hoogte, hoog. Javaansch-Nederduitsch Woordenboek, Gericke en Roorda, 1847, #16.', 3),
(92, 'antal', 'a ntal () : K.N. langzaam. - a ntal- a ntalan, zeerlangzaam. -ngaptalake, langzaam maken. Javaansch-Nederduitsch Woordenboek, Gericke en Roorda, 1847, #16.', 6),
(93, 'anyêp', 'a nyêp (a¥|p) : K.N. koud, koel, frisch. banyu a nyêp, koud, frisch water. Javaansch-Nederduitsch Woordenboek, Gericke en Roorda, 1847, #16.', 8),
(94, 'ocar-acir', 'ocar- a cir (ocar­acIr) : of kocar-kacir, K.N. vermorsen, verkwisten; verkwistend. -ngocar- a cir, verkwisten, vermorsen, op den grond gooijen. Javaansch-Nederduitsch Woordenboek, Gericke en Roorda, 1847, #16.', 2),
(95, 'ara-uru', 'a ra-uru (OrO­uru) : of ura-uru, Kw. verward; onstuimig; uit elkander loopen [Sd. uru- a ra, en Ml. [hiru-hara], verwarring, oploop; vrg. ruara]. Javaansch-Nederduitsch Woordenboek, Gericke en Roorda, 1847, #16.', 3),
(96, 'arèn', 'a rèn (arEn) : K.N. de A ren of palmboom. Javaansch-Nederduitsch Woordenboek, Gericke en Roorda, 1847, #16.', 5),
(97, 'arda', 'a rda (ardO) : Kw. 1º. zeer, uitermate, buitengemeen [= kaliwat]. -2º. kwaad, ondeugend, stout [vrg. rêda] - a rdacăndra, benaming van een slagorde in de Bråtå-yudå. - a rda dêdali, naam van een soort van pijlen. - a rdawalika, naam van een gouden vogel met een slangekop, die tot de vorstelijke staatsie behoort; en ... selengkapnya a rda (ardO) : Kw. 1º. zeer, uitermate, buitengemeen [= kaliwat]. -2º. kwaad, ondeugend, stout [vrg. rêda] - a rdacăndra, benaming van een slagorde in de Bråtå-yudå. - a rda dêdali, naam van een soort van pijlen. - a rdawalika, naam van een gouden vogel met een slangekop, die tot de vorstelijke staatsie behoort; en eign. van den vorst der slangen. Javaansch-Nederduitsch Woordenboek, Gericke en Roorda, 1847, #16.', 3),
(98, 'arum', 'a rum (arUm) : K.N. geurig, welriekend [= wangi, en a wangi, Ml. [h of haruum] Men vindt ook rum, en dit is waarschijnlijk de grondvorm]. sang a rum, een schoon meisje, een jonge vrouw. Javaansch-Nederduitsch Woordenboek, Gericke en Roorda, 1847, #16.', 3),
(99, 'aksara', 'a ksara (aksOrO) : N. [sastra, K.] een letter van het a lphabeth; de letteren, wetenschap [Sd. Ml. id.; Skr. a xara]. putusing a ksara, volleerd in de letteren zijn. Javaansch-Nederduitsch Woordenboek, Gericke en Roorda, 1847, #16.', 2),
(100, 'akil balèg', 'a kil balèg (akIl balEg) : zie a kil. Javaansch-Nederduitsch Woordenboek, Gericke en Roorda, 1847, #16.', 8),
(101, 'aditya', 'a ditya (adityO) : Kw. dezon [= srêngenge, Skr. â ditya]. Javaansch-Nederduitsch Woordenboek, Gericke en Roorda, 1847, #16.', 8),
(102, 'Adam', 'A dam (adam) : eign. A dam. Javaansch-Nederduitsch Woordenboek, Gericke en Roorda, 1847, #16.', 4),
(103, 'adang', 'a dang (adaG) : of a dang, zie dang. Javaansch-Nederduitsch Woordenboek, Gericke en Roorda, 1847, #16.', 9),
(104, 'atasangin', 'a tasangin (atasaGIn) : Ml. [ a tasangin], eign. bovenwindsch; Maleische benaming van de landen westelijk van Java. Javaansch-Nederduitsch Woordenboek, Gericke en Roorda, 1847, #16.', 4),
(105, 'As', 'A s (as) : Kw. een woordje zonder beteckenis [Skr. â s, interj. o!]. Javaansch-Nederduitsch Woordenboek, Gericke en Roorda, 1847, #16.', 9),
(106, 'asih', 'a sih (asIh) : of sih, K.N. gunst, genegenheid, liefde; gunstig; beminnen. -k, of kêkasih, begunstigde, gunsteling, lieveling. -ngasihi, een gunst bewijzen, begunstigen; beminnen; toegenegen, liefderijk. kasihan, K.N., dikasihi, n., dipun kasihi, K., l.v. sinihan, en kinasihan, begunstigd; lieveling. ... selengkapnya a sih (asIh) : of sih, K.N. gunst, genegenheid, liefde; gunstig; beminnen. -kasih, of kêkasih, begunstigde, gunsteling, lieveling. -ngasihi, een gunst bewijzen, begunstigen; beminnen; toegenegen, liefderijk. kasihan, K.N., dikasihi, n., dipun kasihi, K., l.v. sinihan, en kinasihan, begunstigd; lieveling. sih-sinihan, elkander beminnen. -ngasih- a sih, om een gunst smeken; liefkozen, vleijen. -pasih, liefde, genegenheid. -pasihan, of pasiyan, gunstbewijs; de huwelijksliefde van nogjong getrouwden, in de wittebroodsweken zijn. Javaansch-Nederduitsch Woordenboek, Gericke en Roorda, 1847, #16.', 3),
(107, 'asêm', 'a sêm (as|m) : K.N. zuur, wrang [Sd.Ml.id.]. wit a sêm, Tamarinde-boom. - a sêman, iets dat een wrangen smaak heeft; een bitter lijden, wederwaardigheid; de tusschenruimte tusschen de vingers. Javaansch-Nederduitsch Woordenboek, Gericke en Roorda, 1847, #16.', 3),
(108, 'alis', 'a lis (alIs) : N. [ron en imba K.] wenkbraauw, de wenkbraauwen [Sd. Ml. id.]. ngincang a lis, de wenkbraauwen ophalen (een uitdrukking van toorn). Javaansch-Nederduitsch Woordenboek, Gericke en Roorda, 1847, #16.', 3),
(109, 'alip', 'a lip () : A r. A liph, naan van de eerste letter van het A rabische a lphabet, en van het eerste jaar van een Windu. - a lip- a lipan, Kw. de eerste beginselen van een kunst of watenschap. Javaansch-Nederduitsch Woordenboek, Gericke en Roorda, 1847, #16.', 7),
(110, 'alpa daya', 'a lpa daya (alpO dOyO) : zie a lpa. Javaansch-Nederduitsch Woordenboek, Gericke en Roorda, 1847, #16.', 9),
(111, 'alip-alipan', 'a lip- a lipan (alip­alipan) : zie a lip. Javaansch-Nederduitsch Woordenboek, Gericke en Roorda, 1847, #16.', 2),
(112, 'apti', 'a pti () : Kw. [= a rêp]; ngapti, willen, begeeren. kapti, begeerte, verlangen, wensch. ngapti- a pti, verwachten, verlangen; wenschen, hopen. Javaansch-Nederduitsch Woordenboek, Gericke en Roorda, 1847, #16.', 6),
(113, 'adhang', 'a dhang (aDaG) : K.N. op weg tegen komen [Ml. beloeren, belagen, bespieden: vrg. dhang]. -ng op weg a fwachten, op iets of iemand wachten; naar iemand of iets verlangen; heloeren, begluren. ngadhang- a dhang, op weg staan a fwachten. -ngadhangi, iemand met een oogmerk op weg a fwachten, bijv. om hem kwaad te doen, ... selengkapnya a dhang (aDaG) : K.N. op weg tegen komen [Ml. beloeren, belagen, bespieden: vrg. dhang]. -ngadhang op weg a fwachten, op iets of iemand wachten; naar iemand of iets verlangen; heloeren, begluren. ngadhang- a dhang, op weg staan a fwachten. -ngadhangi, iemand met een oogmerk op weg a fwachten, bijv. om hem kwaad te doen, of om hem den weg a f te snijden. -kadhang, zie beneden. Javaansch-Nederduitsch Woordenboek, Gericke en Roorda, 1847, #16.', 5),
(114, 'ajap', 'a jap () : K.N.; ngajap, verlangen, begeeren [ a jap = ngarêp- a rêp]. -pangajapan, een sterk verlangen, een groote begeerte. Javaansch-Nederduitsch Woordenboek, Gericke en Roorda, 1847, #16.', 3),
(115, 'ayah', 'a yah () : Kw. ijzer; ijzeren [Skr. a yah]. Javaansch-Nederduitsch Woordenboek, Gericke en Roorda, 1847, #16.', 2),
(116, 'ayêr', 'a yêr (ay|r) : K.N. de ronde maken; een oppasser. -ng, iets nagaan, het opzigt over iets hebben. ngayêr- a yêr, een gedurig toezigt hebben over iets. Javaansch-Nederduitsch Woordenboek, Gericke en Roorda, 1847, #16.', 6),
(117, 'ayak', 'a yak (aya?) : K.N.; ng, zeven, wannen, ziften [Sd. Ml. a yak, id.]. -ngayaki, iets ziften. -pangayakan, een zeef. Javaansch-Nederduitsch Woordenboek, Gericke en Roorda, 1847, #16.', 5),
(118, 'amrih', 'a mrih (amrIh) : K.N. pogen, trachten, streven, bedoelen, beoogen [= a nêdya. De grondvorm is prih]. -ng, op iets het oog hebben. kaprih, gepoogd; bedoeling. -pamrih, bedoeling, streven [=sêdya en nêdya]. mamrih K.w. z.v. a . a mrih. Javaansch-Nederduitsch Woordenboek, Gericke en Roorda, 1847, #16.', 1),
(119, 'amis', 'a mis (amIs) : K.N. vischreuk, stank, kwade reuk; ongeregeldheid, verkeerdheid; stinken [Ml. id.] a mis bacining nagara, de ongeregeldheden der hoofdflaats of van het rijk. Javaansch-Nederduitsch Woordenboek, Gericke en Roorda, 1847, #16.', 5),
(120, 'ampun', 'a mpun (ampUn) : Ml. [ a mpun], vergiffenis [Jav. a pura N., a puntên K.]. Javaansch-Nederduitsch Woordenboek, Gericke en Roorda, 1847, #16.', 6),
(121, 'ambên', 'a mbên (amb|n) : K.N. gordel, buikriem van een paard. a mbên gendhong, oversingel. -ngêmbêni, omgorden, omwinden, een buikriem omdoen. Javaansch-Nederduitsch Woordenboek, Gericke en Roorda, 1847, #16.', 1),
(122, 'ambil', 'a mbil (ambIl) : Ml. [ a mbil]; ng, nemen, weg nemen [=ngamèk]. -ngambili, iets weg nemen. Javaansch-Nederduitsch Woordenboek, Gericke en Roorda, 1847, #16.', 1),
(123, 'among', 'a mong (amOG) : K.N. het opzigt over iemand houden; een kind oppassen [de grondvorm is mong]]. A mong Praja (z.v. a . Rijksvoogd) eign. van dentijdelijken Hoofd-djêksa, den voorsitter der Pradata te Soerakarta. -ngêmong, oppassen, bedienen; zorg voor iemand dragen, beschermen. -momong of mongmong, het oog op iemand ... selengkapnya a mong (amOG) : K.N. het opzigt over iemand houden; een kind oppassen [de grondvorm is mong]]. A mong Praja (z.v. a . Rijksvoogd) eign. van dentijdelijken Hoofd-djêksa, den voorsitter der Pradata te Soerakarta. -ngêmong, oppassen, bedienen; zorg voor iemand dragen, beschermen. -momong of mongmong, het oog op iemand houden, een kind oppassen, verzorgen, beschermen. -momongan, hetgeen waarover men het opzigt heeft. ingkang darbe momongan, hij die het opzigt over a nderen bezit; een hoofd, zaakbezorger, procureur. -pamomong of pmong, opziener, oppasser, voogd van een kind. Javaansch-Nederduitsch Woordenboek, Gericke en Roorda, 1847, #16.', 7),
(124, 'among praja', 'a mong praja (amoG prOjO) : zie a mong. Javaansch-Nederduitsch Woordenboek, Gericke en Roorda, 1847, #16.', 7),
(125, 'ogal-agil', 'ogal- a gil (ogal­agIl) : K.N. omwippen, omkantelen. wot ogal- a gil, de brug die naar het doodenrijk leidt. Javaansch-Nederduitsch Woordenboek, Gericke en Roorda, 1847, #16.', 6),
(126, 'agop', 'a gop (agOp) : Kw. eindigen, ophouden. tan a gop, niet ophoude, onophoudelijk. Javaansch-Nederduitsch Woordenboek, Gericke en Roorda, 1847, #16.', 2),
(127, 'abra', 'a bra (abrO) : K.N. overal, in het ronde, wijd en zijd verpreid [=warata. Zie ook bra]. a bra puspa, naam van een paard in de Brata-joeda. Javaansch-Nederduitsch Woordenboek, Gericke en Roorda, 1847, #16.', 3),
(128, 'obat-abit', 'obat- a bit (obat­abIt) : K.N.; ngobat- a bit, zwaaijen, zwenken. -mobat-mabit, zwaaijen, heên en weêr slingeren, om zich heen slaan. -ngobat- a bitake N., -kên K., met iets heên en weêr zwaaijen. Javaansch-Nederduitsch Woordenboek, Gericke en Roorda, 1847, #16.', 9),
(129, 'abang', 'a bang (abaG) : N., a brit K., rood [Ml. id. Vrg. bang]. a bang tuwa N., a brit sêpuh K., karmozijn. -ng N., ngabrit K., of ngabangake N., ngabritakên K., rood maken, rood verwen. Javaansch-Nederduitsch Woordenboek, Gericke en Roorda, 1847, #16.', 1),
(130, 'angrêm', 'a ngrêm (aGr|m) : K.N. bestendig op dezelfde plaats blijven zitten. babon a ngrêm, een kip die broeit. Javaansch-Nederduitsch Woordenboek, Gericke en Roorda, 1847, #16.', 6),
(131, 'ăngsa', 'ă ngsa (OGsO) : Kw. [banyak K.N.] een gans [Ml. [ a ngsa] of [kangsa], Sd. gangsa, Skr. hangsa]. Javaansch-Nederduitsch Woordenboek, Gericke en Roorda, 1847, #16.', 5),
(132, 'anglês', 'a nglês (aGl|s) : K.N. I. zich ver uitstrekken. II. den moed laten zinken, moedeloos, terneêr geslagen. III. z.v. a . a nglès [Het wordt verklaard door a nyamar en namar]. Javaansch-Nederduitsch Woordenboek, Gericke en Roorda, 1847, #16.', 5),
(133, 'ăngga', 'ă ngga (OGgO) : Kw. I. water [= banyu]. II. lichaam; voorbeeld, gelijkennis; vorm, gedaante [= badan of sarira, Skr. a ngga, een lid; het lichaam; een hulpmiddel; enz.]. a ngganipun, bij boorbeeld. - ă nggadara, benaming van een wapendrager van den Vorst. Ă nggajali, eign. van een zoon van Bramakêndali. Javaansch-Nederduitsch Woordenboek, Gericke en Roorda, 1847, #16.', 5),
(134, 'kaladhangastra', 'kaladhang a stra (kalaDaG astrO) : zie kadhang a stra. Javaansch-Nederduitsch Woordenboek, Gericke en Roorda, 1847, #16.', 9),
(135, 'kadhangastra', 'kadhang a stra (kaDaG astrO) : en kaladhang a stra, naam van een pijl. Javaansch-Nederduitsch Woordenboek, Gericke en Roorda, 1847, #16.', 1),
(136, 'pritanjala', 'prit a njala (prIt anjOlO) : of prit a njala, eign. van één der negen Djawåtå''s, in de Manik-måjå. Javaansch-Nederduitsch Woordenboek, Gericke en Roorda, 1847, #16.', 7),
(137, 'mangangên-angên', 'mangangên- a ngên (maGaG|n­aG|n) : K.N. overdenken, overleggen [van a ngên]. Javaansch-Nederduitsch Woordenboek, Gericke en Roorda, 1847, #16.', 8),
(138, 'ngancam-ancam', 'ngancam- a ncam (Gancam­ancam) : K.N. dreigen, waarschuwen. -pangancam- a ncam, bedreiging. Javaansch-Nederduitsch Woordenboek, Gericke en Roorda, 1847, #16.', 5),
(139, 'ngănta-ănta', 'ngănta- ă nta (GOntO­OntO) : K.N. vast er op rekenen [grondvorm ă nta, poët. het vast er op rekenen]. Javaansch-Nederduitsch Woordenboek, Gericke en Roorda, 1847, #16.', 8),
(140, 'ngati-ati', 'ngati- a ti (Gati­ati) : zie a ti, I. Javaansch-Nederduitsch Woordenboek, Gericke en Roorda, 1847, #16.', 2),
(141, 'andhap', 'a ndhap (anDap) : - a ndhap- a ndhapan, zie bij sosor, -kaping, zie beneden. Javaansch-Nederduitsch Woordenboek, Gericke en Roorda, 1847, #16.', 10),
(142, 'arang', 'a rang (araG) : - a rang en ngangrangan, zie beneden. Javaansch-Nederduitsch Woordenboek, Gericke en Roorda, 1847, #16.', 1),
(143, 'adi', 'a di () : -ngadi- a di, N., ngados- a dos, K., en ngadèkake, N., -kên, K., z.ben. Javaansch-Nederduitsch Woordenboek, Gericke en Roorda, 1847, #16.', 3),
(144, 'asah', 'a sah () : -ngasahi zie a sah, beneden. Javaansch-Nederduitsch Woordenboek, Gericke en Roorda, 1847, #16.', 2),
(145, 'agra', 'a gra (agrO) : is het Skr. a gra, dat hetzelfde beteekent. Javaansch-Nederduitsch Woordenboek, Gericke en Roorda, 1847, #16.', 9),
(146, 'angah', 'a ngah (aGah) : zie ng- a ngah, en mangah-mangah. Javaansch-Nederduitsch Woordenboek, Gericke en Roorda, 1847, #16.', 7),
(147, 'andha', 'a ndha (anDa) : (Tg.) ă ndha. Javaansche Woordenlijst, De Nooy, 1893, #24.', 6),
(148, 'anjan', 'a njan () : a njan- a njanên, (m.) jinja. (Bn.) a nji- a njinên. Javaansche Woordenlijst, De Nooy, 1893, #24.', 10),
(149, 'anjuk', 'a njuk (anjU?) : ng, (Bg.) banjur. J. utang. Têmbung a njuk, ing Sk. ora nganggo, dene a raning dhistrik Nganjuk, kaanggêp têmbung lingga, padhane: Ngawi Magêtan. Javaansche Woordenlijst, De Nooy, 1893, #24.', 9),
(150, 'awik', 'a wik (awIk) : K. (Bl.) suwawi, manawa saka rusaking têmbung wawi = suwawi dadi a wik. Javaansche Woordenlijst, De Nooy, 1893, #24.', 4),
(151, 'aluk', 'a luk (alU?) : (C.) a nguk = a thuk, a luk êndi kowe dirès. Javaansche Woordenlijst, De Nooy, 1893, #24.', 7),
(152, 'alim', 'a lim () : A rb. suthik Mg. ing Sk. têmbung a lim = maklum, kaya ta: a liman = makluman. Javaansche Woordenlijst, De Nooy, 1893, #24.', 3),
(153, 'apuntên', 'a puntên (apunt|n) : k. êmbuh C. (M.) têmbung a puntên saka a pura. Javaansche Woordenlijst, De Nooy, 1893, #24.', 10),
(154, 'ajok', 'a jok (ajOk) : ng (Kr.) kêduwung. têmbung a jok saka a ju. Javaansche Woordenlijst, De Nooy, 1893, #24.', 3),
(155, 'ayang', 'a yang (ayaG) : a yang- a yangan (Bn.) wawan. Javaansche Woordenlijst, De Nooy, 1893, #24.', 10),
(156, 'ambêg', 'a mbêg (amb|g) : a mpêk Kd. bakone a mpang bae ora a mbêg = ora a mpêk. Javaansche Woordenlijst, De Nooy, 1893, #24.', 4),
(157, 'agèn', 'a gèn (agEn) : (Sm.) a gi utawa lagi. a gèn saiki = lagi saiki. Javaansche Woordenlijst, De Nooy, 1893, #24.', 7),
(158, 'agêp', 'a gêp (ag|p) : (Pb., Bs.) a rêp = bakal, a ku a gêp lunga, a ku a rêp lunga. Javaansche Woordenlijst, De Nooy, 1893, #24.', 6),
(159, 'abit', 'a bit (abIt) : wiwit, Bn., Pd., (Bn.) saka rusaking têmbung a wit, dadi a bit. Javaansche Woordenlijst, De Nooy, 1893, #24.', 7),
(160, 'angklèng', 'a ngklèng (aGklEG) : Ls. (Rmb.) ngêlong. gonmu a ngklèng = ngêlong bêras têlung bêruk bae. Javaansche Woordenlijst, De Nooy, 1893, #24.', 10),
(161, 'angga', 'a ngga (aGga) : kw. upama Tgl. Têmbung a ngga manawa saka rusakaning têmbung, saenggo. Javaansche Woordenlijst, De Nooy, 1893, #24.', 6),
(162, 'abab', 'a bab () : kn hawa saka ing cangkêm, mung [x] bae pc: mung swara thok ora a na kanyatakane, di-[x]- i: didamoni, dikênani a bab, kc. kababan. Bausastra Jawa, Poerwadarminta, 1939, #75.', 6),
(163, 'abên', 'a bên (ab|n) : I êngg 1 s, 2 (ut. a bèn) kêrêp. II dipun-[x] k: diadu, [x]-[x]- a n k: a don- a don. Bausastra Jawa, Poerwadarminta, 1939, #75.', 5),
(164, 'abrik', 'a brik (abrI?) : diobrak- a brik kn dirusak bosah-basih. Bausastra Jawa, Poerwadarminta, 1939, #75.', 6),
(165, 'absah', 'a bsah () : kn 1 wis miturut surasaning wêwaton ut. a nggêr- a nggêr (lumrahe tmr.babagan a gama Islam), 2 êngg, pc. wis bèrès, wis lunas, di-[x]- a ke: dianggêp (ditêtêpake) a bsah. Bausastra Jawa, Poerwadarminta, 1939, #75.', 1),
(166, 'adan', 'a dan () : I ( A ) kn a lok- a lok dianggo ngelingake supaya padha salat, di-[x]-i a k: dielingake sarana a dan. II di-[x]-i êngg kn: 1 diawat- a wati, dirigênake (tmr. pagaweyan), 2 diladèni, kc dandan. Bausastra Jawa, Poerwadarminta, 1939, #75.', 5),
(167, 'adol', 'a dol (adOl) : n. sade k 1 nawakake (nglilakake, mènèhake) barang dêdagangane (wêwênange lsp.) marang liyan kalawan lêliru dhuwit; 2 ent. ngaton-ngatonake, mamèrake; [x] a yu ([x] bagus): mamèrake a yun ([x] bagus): mamèrake a yune (baguse) supaya disênêngi; [x] a wèh tuku a rêp pc: têtêmbungane wong dodolan ... selengkapnya a dol (adOl) : n. sade k 1 nawakake (nglilakake, mènèhake) barang dêdagangane (wêwênange lsp.) marang liyan kalawan lêliru dhuwit; 2 ent. ngaton-ngatonake, mamèrake; [x] a yu ([x] bagus): mamèrake a yun ([x] bagus): mamèrake a yune (baguse) supaya disênêngi; [x] a wèh tuku a rêp pc: têtêmbungane wong dodolan mratelakake yèn rêgane barange ora larang; [x] gawe: ngaton-ngatonake pagaweane supaya diaranana srêgêp; [x] gêmbès ks: laku palanyahan; [x] gêndhung pc: kumingsun, umuk; [x] lêpas ([x] têrus, [x] plas): a dol palêmahane lsp. ora bakal ditêbus manèh: [x] umuk ([x] sêngung): sênêng sêsongaran: [x] gadhe ([x]sendhe): nggadhèkake palêmahane lsp: kulak warta [x] prungon pr: ngrungok-ngrungokake pawarta: [x] swara: ngapus- a pusi; [x] taunan: nyewakake palêmahane (sawahe); kc. dol, dodol. Bausastra Jawa, Poerwadarminta, 1939, #75.', 10),
(168, 'aja', 'a ja (OjO) : n. sampun k ora kêna (nindakake, nglakoni), ora prayoga yèn; [x] manèh ([x] silih êngg): 1 ora mung ... bae, sanadyan ...; 2 bok iya ... pisan; [x] sing ([x] manèh): ora mung ... bae, sanadyana (malah, bok iya) ...; [x] pisan (-pisan): ora kêna babar pisan (pamênging); [x] sok: ora prayoga yèn; [x] ... selengkapnya a ja (OjO) : n. sampun k ora kêna (nindakake, nglakoni), ora prayoga yèn; [x] manèh ([x] silih êngg): 1 ora mung ... bae, sanadyan ...; 2 bok iya ... pisan; [x] sing ([x] manèh): ora mung ... bae, sanadyana (malah, bok iya) ...; [x] pisan (-pisan): ora kêna babar pisan (pamênging); [x] sok: ora prayoga yèn; [x] nganti: supaya ora; [x] ta ([x] si, [x] sinèh êngg): bok iya a ja (nindakake); [x] sik ([x] dhisik): mêngko dhisik! [x] tan ora br: ora kêna ora, kudu; dini kn: diojok-ojoki, dikon supaya nindakake. Bausastra Jawa, Poerwadarminta, 1939, #75.', 4),
(169, 'ajang', 'a jang (ajaG) : kn 1 wêwadhahing sêga kang dipangan (piring lsp); 2 ent. papan kang dianggo (pêrang, karamean lsp.); tunggal [x] pc: tunggal pagawean; di-[x]-i: diwènèhi a jang; 2 ent. disêdiyani papan dianggo (pista, pakumpulan lsp). Bausastra Jawa, Poerwadarminta, 1939, #75.', 5),
(170, 'ajêg', 'a jêg (aj|g) : kn 1 têtêp ora owah-owah; 2 tansah bola-bali; di-[x]- a ke: digawe a jêg, dilêstarèkake; [x]- a n pc: tansah, pijêr. Bausastra Jawa, Poerwadarminta, 1939, #75.', 6),
(171, 'adhèhan', 'a dhèhan (aDEhan) : kn nyirig bantêr (tmr. lakuning jaran): diadhèhake: dilakokake a dhèhan. Bausastra Jawa, Poerwadarminta, 1939, #75.', 6),
(172, 'adhuk', 'a dhuk (aDU?) : di-[x] êngg. kn dipaculi didhudhukake; kc. campur a dhuk. Bausastra Jawa, Poerwadarminta, 1939, #75.', 7),
(173, 'alang-ujur', 'a lang-ujur (alaG­ujUr) : kn 1 a mba sarta dawane; 2 ent. pêrnah, dunung: ora wêruh a lang-ujure; ora wêruh kn: dijupuk, dipèk pêrnahe (ênggone mati). Bausastra Jawa, Poerwadarminta, 1939, #75.', 3),
(174, 'alas', 'a las () : n. wana k 1 palêmahan jêmbar sing kêbak ing witwitan gêdhe-gêdhe; 2 êngg. têgal; [x]- a n n. wanan k: 1 kang durung digarap ing wong; 2 kang manggon ing a las. Bausastra Jawa, Poerwadarminta, 1939, #75.', 5),
(175, 'alas gung', 'a las gung (alas gUG) : (-liwang-liwung) br a las gêdhe bangêt. Bausastra Jawa, Poerwadarminta, 1939, #75.', 8),
(176, 'alik', 'a lik (alI?) : I ut. a lika êngg. pc. a luwung. II ng-[x]-[x] êngg. kn: g-galik (tmr.swara). III di-[x] êngg. pc: diwalik; kc. olak- a lik. Bausastra Jawa, Poerwadarminta, 1939, #75.', 4),
(177, 'amblês', 'a mblês (ambl|s) : kn mblêdhês (mlêbu) ing banyu ( a mblês lsp). Bausastra Jawa, Poerwadarminta, 1939, #75.', 3),
(178, 'amin', 'a min () : ( A ) kn muga kêlakona mangkono (dianggo ing pungkasaning sêmbahyang); [x]-[x] êngg. pc: kêndurèn, slamêtan; di-[x]-i: 1 diwangsuli a min; 2 dimupakati dirujuki. Bausastra Jawa, Poerwadarminta, 1939, #75.', 4),
(179, 'among kisma', 'a mong kisma (amOG kIsmO) : kw kc. a mong tani. Bausastra Jawa, Poerwadarminta, 1939, #75.', 5),
(180, 'ana', 'a na (OnO) : n. wontên k 1 katon maujud (mawa blêgêr); 2 pancèn nyata madêg; 3 dumunung ing, kapêrnah ing; 4 pc. duwe, kadunungan; 5 pc. manggon, dêdunung ing; 5 pc. dadi ut. padha karo, up. 4 ping 4 a na 16; [x] dene n. wondening k: dene mungguh ing..; dini, dianakake: diwujudi, dicêpakake; kc. kaanan, ... selengkapnya a na (OnO) : n. wontên k 1 katon maujud (mawa blêgêr); 2 pancèn nyata madêg; 3 dumunung ing, kapêrnah ing; 4 pc. duwe, kadunungan; 5 pc. manggon, dêdunung ing; 5 pc. dadi ut. padha karo, up. 4 ping 4 a na 16; [x] dene n. wondening k: dene mungguh ing..; dianani, dianakake: diwujudi, dicêpakake; kc. kaanan, kahanan. Bausastra Jawa, Poerwadarminta, 1939, #75.', 5),
(181, 'anakangkat', 'a nak a ngkat (ana? aGkat) : kn a nak pèkpèkan. Bausastra Jawa, Poerwadarminta, 1939, #75.', 7),
(182, 'anak mas', 'a nak mas (ana? mas) : kn 1 panyêbut marang kaponakan (wong kapêrnah nom lsp) tmr. para luhur; 2 bocah Jawa lsp.kang dipèk a nak bangsa Wlanda. Bausastra Jawa, Poerwadarminta, 1939, #75.', 8),
(183, 'anak pupon', 'a nak pupon (ana? pupOn) : kn a nak pèkpèkan wiwit cilik mula. Bausastra Jawa, Poerwadarminta, 1939, #75.', 6),
(184, 'anjal', 'a njal () : (- a njal) êngg. kn tansah lunga (klintong). Bausastra Jawa, Poerwadarminta, 1939, #75.', 10),
(185, 'anjir', 'a njir (anjIr) : kn 1 pathokan dawa dianggo têtêngêr lsp; 2 êngg. kuli padesan kang pinatah ndandani dalan; di-[x]-i: dipasangi a njir. Bausastra Jawa, Poerwadarminta, 1939, #75.', 1),
(186, 'andhingane', 'a ndhingane (anDiGane) : êngg wingi; a ndhingane wingi êngg: wingènane. Bausastra Jawa, Poerwadarminta, 1939, #75.', 2),
(187, 'anthok', 'a nthok (anTO?) : kn 1 tlakupaning jantung gêdhang lsp; 2 barang (kayu lsp) tipis kang ditèmplèkake ing sambungan dianggo pikukuh; 3 klikaning kulit lsp. ditrap ing tangan lsp. kang kêsliyo; di-[x]-i: 1 ditrapi a nthok; 2 ks. disanggama. Bausastra Jawa, Poerwadarminta, 1939, #75.', 8),
(188, 'angin dharat', 'a ngin dharat (aGin Darat) : kn a ngin kang pinangkane saka ing dharatan. Bausastra Jawa, Poerwadarminta, 1939, #75.', 3),
(189, 'angin laut', 'a ngin laut (agin laUt) : kn a ngin kang pinangkane saka sagara. Bausastra Jawa, Poerwadarminta, 1939, #75.', 8),
(190, 'angka', 'a ngka (OGkO) : I kn 1 tulisan gambaring cacah; 2 nomêr; [x] urut: nomêr kang urut-urutan; [x]-ning taun: cacah kang mratelakake petunganing taun; dini: dicirèni ing a ngka. II êngg. kn: niyat, kang dituju (dikarêpake); di-[x]-[x] êngg: tansah diniyati, dirêrantam. Bausastra Jawa, Poerwadarminta, 1939, #75.', 8),
(191, 'arêm', 'a rêm (ar|m) : di-[x]-[x]-i kn dilipur supaya nrima sarana disaguhi a rêp diwêwènèhi lsp: kc. m, pangarêm- a rêm. Bausastra Jawa, Poerwadarminta, 1939, #75.', 2),
(192, 'arêng watu', 'a rêng watu (ar|G watu) : n. ([x] sela k) a rêng kang a sal saka kayu kang kapêndhêm ing sajroning lêmah. Bausastra Jawa, Poerwadarminta, 1939, #75.', 4),
(193, 'acar', 'a car () : I kn lêlawuhan kang digawe wowohan lsp. dicêncêm ing cokak ( a sêm); di-[x]: diolah a car. II di-[x] kn. êngg: 1 ditrajang, diancab; 2 diancang- a ncangi; 3 ditumbuk, dibijig; kc. a ncar. Bausastra Jawa, Poerwadarminta, 1939, #75.', 3),
(194, 'bak-ayu', 'bak- a yu (ba?­ayu) : êngg.kn bok- a yu. Bausastra Jawa, Poerwadarminta, 1939, #75.', 6),
(195, 'clèmètane', 'clèmèt a ne (clEmEt ane) : (ut. cilèmèt a ne) êngg. pc: wah cilaka! Bausastra Jawa, Poerwadarminta, 1939, #75.', 4),
(196, 'clènthingane', 'clènthing a ne (clEnTIG ane) : (ut. cilenthing a ne) êngg. pc. wah cilaka! Bausastra Jawa, Poerwadarminta, 1939, #75.', 6),
(197, 'clomotane', 'clomot a ne (clOmOt ane) : (ut. cilomot a ne) pc: cilaka ! Bausastra Jawa, Poerwadarminta, 1939, #75.', 1),
(198, 'dèn-ajêng', 'dèn- a jêng (dEn­aj|G) : pc radèn a jêng. Bausastra Jawa, Poerwadarminta, 1939, #75.', 6),
(199, 'dèn-ayu', 'dèn- a yu (dEn­ayu) : pc radèn a yu. Bausastra Jawa, Poerwadarminta, 1939, #75.', 2),
(200, 'gêdhang-ayu', 'gêdhang- a yu (g|DaG­ayu) : n. pisang- a yu k:gêdhang isih wutuh dianggo slamêtan. Bausastra Jawa, Poerwadarminta, 1939, #75.', 3),
(201, 'insaallah', 'insa'' a llah (insa?alah) : ( A ) kn yèn Gusti A llah marêngake. Bausastra Jawa, Poerwadarminta, 1939, #75.', 9),
(202, 'katrêsanatine', 'katrêsan a tine (katr|san atine) : br sêdhih bangêt a tine; kc. têrês. Bausastra Jawa, Poerwadarminta, 1939, #75.', 4),
(203, 'kawut-awut', 'kawut- a wut (kawUt­awUt) : br diawut- a wut. Bausastra Jawa, Poerwadarminta, 1939, #75.', 7),
(204, 'kêjaitatine', 'kêjait a tine (k|jaIt atine) : br kêkênan bangêt a tine; kc. jait. Bausastra Jawa, Poerwadarminta, 1939, #75.', 9),
(205, 'kênang-apa', 'kênang- a pa (k|naG­OpO) : êngg. pc geneya, sabab a pa. Bausastra Jawa, Poerwadarminta, 1939, #75.', 3),
(206, 'kênèngapa', 'kênèng a pa (k|nEG OpO) : (-gene) êngg. pc geneya, sabab a pa. Bausastra Jawa, Poerwadarminta, 1939, #75.', 5),
(207, 'kênong-apa', 'kênong- a pa (k|nOG­OpO) : (-gene) êngg. pc geneya, sabab a pa. Bausastra Jawa, Poerwadarminta, 1939, #75.', 7),
(208, 'koran', 'kor'' a n (kor an) : ( A ) kn. kitab suci Islam; kc. kur'' a n. Bausastra Jawa, Poerwadarminta, 1939, #75.', 1),
(209, 'lara-ayu', 'lara- a yu (lOrO­ayu) : n. sakit- a yu k: lara cacar. Bausastra Jawa, Poerwadarminta, 1939, #75.', 6),
(210, 'limangatus', 'limang a tus (limaG atUs) : (ewu lsp) n. gangsal a tus (èwu lsp) k. 500 (5000 lsp). Bausastra Jawa, Poerwadarminta, 1939, #75.', 9),
(211, 'mantri-alas', 'mantri- a las (mantri alas) : (-blandhong): a r. punggawa Nêgara kang pinatah ngawat- a wati a las pajatèn. Bausastra Jawa, Poerwadarminta, 1939, #75.', 3),
(212, 'maraawak', 'mara a wak (mOrO awa?) : n. (-bau k), mara bau kn. rewang ut. têka nyambut gawe mung a wak thok (tanpa piranti, pasumbang lsp). Bausastra Jawa, Poerwadarminta, 1939, #75.', 9),
(213, 'nikêlalis', 'nikêl a lis (nik|l alIs) : br. njêngkêrutake a lis. Bausastra Jawa, Poerwadarminta, 1939, #75.', 3),
(214, 'ngabul-abul', 'ngabul- a bul (GabUl­abUl) : êngg. kn. ngudhal-udhal (mbuwangi, mratakake lsp) mênyang êndi-êndi; kc. a bul, mabul. Bausastra Jawa, Poerwadarminta, 1939, #75.', 8),
(215, 'ngabrut-abrut', 'ngabrut- a brut (GabrUt­abrUt) : pc. 1 ngudhal-udhal; 2 ngêcèh-êcèh; kc. a brut. Bausastra Jawa, Poerwadarminta, 1939, #75.', 9),
(216, 'ngada-ada', 'ngada- a da (GOdO­OdO) : kn. a k. ngadani; kc. a da. Bausastra Jawa, Poerwadarminta, 1939, #75.', 3),
(217, 'ngadi-adi', 'ngadi- a di (Gadi­adi) : kn. 1 a k. ngaji- a ji, ngêmi-êmi; 2 pc. ugungan bangêt; kc. a di. Bausastra Jawa, Poerwadarminta, 1939, #75.', 9),
(218, 'ngadhag-adhag', 'ngadhag- a dhag (GaDag­aDag) : kn. a k. ngênthak-ênthak ora katutupan; kc. a dhag. Bausastra Jawa, Poerwadarminta, 1939, #75.', 1),
(219, 'ngadhul-adhul', 'ngadhul- a dhul (GaDUl­aDUl) : kn. ngudhal-udhal lan ngawut- a wut; kc. a dhul, madhul. Bausastra Jawa, Poerwadarminta, 1939, #75.', 5),
(220, 'ngagak-agak', 'ngagak- a gak (Gaga?­aga?) : kn. ora turu-turu marga a kèh sing dirasakake; kc. a gak. Bausastra Jawa, Poerwadarminta, 1939, #75.', 4),
(221, 'ngagru-agru', 'ngagru- a gru (Gagru­agru) : pc. ngrusuhi, mbêbeda, ngganggu gawe; kc. a gru. Bausastra Jawa, Poerwadarminta, 1939, #75.', 10),
(222, 'ngaya-aya', 'ngaya- a ya (GOyO­OyO) : kn. nindakake (nggarap) kanthi rêkasa; kc. a ya. Bausastra Jawa, Poerwadarminta, 1939, #75.', 10),
(223, 'ngayam-alas', 'ngayam- a las (Gayam­alas) : (-wana) kw. lunga nusup-nusup (dhêdhêmitan) kaya a yam a las. Bausastra Jawa, Poerwadarminta, 1939, #75.', 5),
(224, 'ngayêng-ayêng', 'ngayêng- a yêng (Gay|G­ay|G) : êngg. kn. mayêng-mayêng; ngayêngi êngg: nganglangi, ngubêngi; kc. a yêng. Bausastra Jawa, Poerwadarminta, 1939, #75.', 8),
(225, 'ngalo-alo', 'ngalo- a lo (Galo­alo) : êngg. kn. kêpengin bangêt; kc. a lo. Bausastra Jawa, Poerwadarminta, 1939, #75.', 6),
(226, 'ngambak-ambak', 'ngambak- a mbak (Gamba?­amba?) : kw. gêgolongan ing êndi-êndi; kc. a mbak. Bausastra Jawa, Poerwadarminta, 1939, #75.', 1),
(227, 'ngambrah-ambrah', 'ngambrah- a mbrah (Gambrah­ambrah) : êngg. kn. sumrambah, sumêbar; kc. a mbrah. Bausastra Jawa, Poerwadarminta, 1939, #75.', 5),
(228, 'ngamu-amu', 'ngamu- a mu (Gamu­amu) : kw. ngundhat-undhat; kc. a mu. Bausastra Jawa, Poerwadarminta, 1939, #75.', 2),
(229, 'ngandhar-andhar', 'ngandhar- a ndhar (GanDar­anDar) : kn. nglantrah bangêt (tmr. crita lsp); ngandharake: nyritakake kalawan rowa; kc. a ndhar. Bausastra Jawa, Poerwadarminta, 1939, #75.', 3),
(230, 'nganta-anta', 'nganta- a nta (GOntO­OntO) : kw. kêpengin bangêt (kumudu malês lsp); kc. a nta. Bausastra Jawa, Poerwadarminta, 1939, #75.', 2),
(231, 'ngancang-ancang', 'ngancang- a ncang (GancaG­ancaG) : kn. cêcawis duwe gawe lsp; ngancang- a ncangi: nata jangkah (mundur) a rêp mlumpat; kc. a ncang. Bausastra Jawa, Poerwadarminta, 1939, #75.', 6),
(232, 'ngangah-angah', 'ngangah- a ngah (GaGah­aGah) : kn. kêpengin (ngarêp- a rêp) bangêt a rêp mêmangan lsp; kc. a ngah. Bausastra Jawa, Poerwadarminta, 1939, #75.', 2),
(233, 'nganggang-anggang', 'nganggang- a nggang (GaGgaG­aGgaG) : kn. nyêkêl lsp. ora diênêtake; kc. a nggang. Bausastra Jawa, Poerwadarminta, 1939, #75.', 2),
(234, 'ngangkas-angkas', 'ngangkas- a ngkas (GaGkas­aGkas) : kw. 1 mindêng, mênêng; 2 nggêgadhang; kc. a ngkas. Bausastra Jawa, Poerwadarminta, 1939, #75.', 6),
(235, 'ngangkrik-angkrik', 'ngangkrik- a ngkrik (GaGkri?­aGkri?) : kn. 1 mangklik-mangklik; 2 dhiri, pambêkan; 3 pc. mangkring (larang bangêt tmr. rêrêgan lsp); kc. a ngkrik. Bausastra Jawa, Poerwadarminta, 1939, #75.', 8),
(236, 'ngarab-arab', 'ngarab- a rab (Garab­arab) : kw. murub mubyar-mubyar; kc. a rab. Bausastra Jawa, Poerwadarminta, 1939, #75.', 9),
(237, 'ngasih-asih', 'ngasih- a sih (GasIh­asIh) : kn. ngrêrêpa kanthi têmbung manis; ngasihi: nrêsnani; kc. sih, a sih, kasih. Bausastra Jawa, Poerwadarminta, 1939, #75.', 8),
(238, 'ngawud-awud', 'ngawud- a wud (GawUd­awUd) : kn. 1 njuwing-juwing, ngudhal-udhal; 2 nyêbar mrana-mrana; kc. a wud. Bausastra Jawa, Poerwadarminta, 1939, #75.', 2),
(239, 'ngawug-awar', 'ngawug- a war (GawUg­awar) : ngaub-(g) a war pc. ngawag, ngawur. Bausastra Jawa, Poerwadarminta, 1939, #75.', 6),
(240, 'ngawul-awul', 'ngawul- a wul (GawUl­awUl) : kn. ngudhal-udhal kapuk lsp; kc. a wul. Bausastra Jawa, Poerwadarminta, 1939, #75.', 7),
(241, 'ngêrta-aji', 'ngêrta- a ji (G|rtO­aji) : kn. a k. nêpsir, ngira-ira; kc. kêrta- a ji. Bausastra Jawa, Poerwadarminta, 1939, #75.', 8),
(242, 'ngincangakealis', 'ngincangake a lis (GincaGake alIs) : kw. ngobahake a lis; kc. kincang. Bausastra Jawa, Poerwadarminta, 1939, #75.', 2),
(243, 'nglarakakeati', 'nglarakake a ti (Glara?ake ati) : n. nyakitakên manah k. nyêrikake a ti; kc. lara. Bausastra Jawa, Poerwadarminta, 1939, #75.', 8),
