(2897, 'dhongoh', 'd hongoh (DOGOh) : K.N. een groot en d ik lichaam. Javaansch-Nederduitsch Woordenboek, Gericke en Roorda, 1847, #16.', 8),
(2898, 'dhanghyang', 'd hanghyang (DaGhyaG) : Kw. een heilige of priester, d ie aan een D éwå nabij komt. Javaansch-Nederduitsch Woordenboek, Gericke en Roorda, 1847, #16.', 5),
(2899, 'dhêngên', 'd hêngên (D|G|n) : K.N. een kwade geest, d ie een ziekte veroorzaakt. Javaansch-Nederduitsch Woordenboek, Gericke en Roorda, 1847, #16.', 9),
(2900, 'dhingin', 'd hingin (DiGIn) : zie d hihin. Javaansch-Nederduitsch Woordenboek, Gericke en Roorda, 1847, #16.', 8),
(2901, 'dhêngêr', 'd hêngêr (D|G|r) : of d hèngêr, N. verstaan, verstand van iets hebben, begrijpen [Ml. d engar], hooren]. Javaansch-Nederduitsch Woordenboek, Gericke en Roorda, 1847, #16.', 4),
(2902, 'dhăngka', 'd hăngka (DOGkO) : K.N. het verblijf of d e woning van een Boetå; een gemeen, slecht huis. adha, zijn verblijf houden, van een Boetå; een slecht huis bewonen. d hangkamu ngêndi, waar is uw huis? waar woont ge? Javaansch-Nederduitsch Woordenboek, Gericke en Roorda, 1847, #16.', 4),
(2903, 'dhingkul', 'd hingkul (DiGkUl) : K.N. zich bukken, gebogen [= tumungkul]. d hingkal- d hingkul, zich aanhoudend bukken, gebogen, krom gaan of zitten. Javaansch-Nederduitsch Woordenboek, Gericke en Roorda, 1847, #16.', 8),
(2904, 'dhungkul', 'd hungkul (DuGkUl) : K.N. d e horens van een buffel, d ie los aan d en kop hangen. Javaansch-Nederduitsch Woordenboek, Gericke en Roorda, 1847, #16.', 10),
(2905, 'dhongkol', 'd hongkol (DOGkOl) : K.N. d oor een anderen in eenen post vervangen worden. Javaansch-Nederduitsch Woordenboek, Gericke en Roorda, 1847, #16.', 10),
(2906, 'dhingklik', 'd hingklik (DiGklI?) : K.N. bank, voetbankje; laag schrijflessenaartje. d ha, naar een D ingklik gelijken. Javaansch-Nederduitsch Woordenboek, Gericke en Roorda, 1847, #16.', 10),
(2907, 'dhingkluk', 'd hingkluk (DiGklU?) : z.v.a. d hêngkluk. Javaansch-Nederduitsch Woordenboek, Gericke en Roorda, 1847, #16.', 2),
(2908, 'dhangdhanggula', 'd hangdhanggula (DaGDaGgulO) : N., d hangdhanggêndhis, K., d e suikerkraai; naam van een zangwijze. II. K.N. beitel. III. Kw. hoop, verwachting [= ngajap, vrg. d hang]. -andhangdhang, K.N. naar iets kwaads verlangen, kwaad bedoelen. Javaansch-Nederduitsch Woordenboek, Gericke en Roorda, 1847, #16.', 1),
(2909, 'dhêngdhêng', 'd hêngdhêng (D|GD|G) : zie d hêndhêng. Javaansch-Nederduitsch Woordenboek, Gericke en Roorda, 1847, #16.', 9),
(2910, 'dhingdhing', 'd hingdhing (DIGDIG) : zie d hing. Javaansch-Nederduitsch Woordenboek, Gericke en Roorda, 1847, #16.', 2),
(2911, 'dhèngdhèng', 'd hèngdhèng (DEGDEG) : zie d hèndhèng. Javaansch-Nederduitsch Woordenboek, Gericke en Roorda, 1847, #16.', 2),
(2912, 'dhêngglêng', 'd hêngglêng (D|Ggl|G) : N. d om, onverstandig, gek. Javaansch-Nederduitsch Woordenboek, Gericke en Roorda, 1847, #16.', 5),
(2913, 'mawidara', 'mawi d ara (mawi dOrO) : Kw. d e eerste d ag d er nieuwe maan [= tanggal pisan]. Javaansch-Nederduitsch Woordenboek, Gericke en Roorda, 1847, #16.', 4),
(2914, 'daraka', 'd araka (darOkO) : Skr. d hâraka, hetgeen iets vat of inhoudt. Javaansch-Nederduitsch Woordenboek, Gericke en Roorda, 1847, #16.', 8),
(2915, 'dirada', 'd irada (dirOdO) : Skr. d wirada, een olifant. Javaansch-Nederduitsch Woordenboek, Gericke en Roorda, 1847, #16.', 1),
(2916, 'dud', 'd ud (dUd) : zie d ut. Javaansch-Nederduitsch Woordenboek, Gericke en Roorda, 1847, #16.', 7),
(2917, 'dadra', 'd adra (dOdrO) : Skr. d râ, wegloopen, vlugten. Javaansch-Nederduitsch Woordenboek, Gericke en Roorda, 1847, #16.', 6),
(2918, 'dêdaman', 'd êdaman (d|daman) : van het Skr. d ama, zelfsbeheersching. Javaansch-Nederduitsch Woordenboek, Gericke en Roorda, 1847, #16.', 1),
(2919, 'dut', 'd ut (dUt) : of d ud, grondvorm van d u en udud. Javaansch-Nederduitsch Woordenboek, Gericke en Roorda, 1847, #16.', 5),
(2920, 'daya', 'd aya (dOyO) : Skr. d âja, gift; ook aandeel. -ngu, zie beneden. Javaansch-Nederduitsch Woordenboek, Gericke en Roorda, 1847, #16.', 9),
(2921, 'dayi', 'd ayi () : bladz. 246, b, r. 2v.o. Lees d ayita. Javaansch-Nederduitsch Woordenboek, Gericke en Roorda, 1847, #16.', 5),
(2922, 'deya', 'd eya (deyO) : Skr. d êha, het lichaam. Javaansch-Nederduitsch Woordenboek, Gericke en Roorda, 1847, #16.', 1),
(2923, 'dibya', 'd ibya (dibyO) : Skr. d iwja, godlijk; schoon, verrukkelijk. Javaansch-Nederduitsch Woordenboek, Gericke en Roorda, 1847, #16.', 9),
(2924, 'Durèn', 'D urèn (durEn) : d uryan. Dasanama Kawi, Padmasusastra, 1897, #18.', 3),
(2925, 'Dariji', 'D ariji (dariji) : d ariji manis | d amika | suwedha | jari | jari madu | nyari. Dasanama Kawi, Padmasusastra, 1897, #18.', 3),
(2926, 'Dewa', 'D ewa (dewO) : apsara | hyang | nasa | d ewata | surapsara | suragana | sidyagana | widhadara | widhasadya | jawata | bathara. Dasanama Kawi, Padmasusastra, 1897, #18.', 4),
(2927, 'Panungguldriji', 'Panunggul d riji (panuGgUl driji) : ulujari | nyaka | d irgajari | têkukan | panika | panalika. Dasanama Kawi, Padmasusastra, 1897, #18.', 4),
(2928, 'Dhuwêt', 'D huwêt (Duw|t) : kêthilêng | d uhêt. Dasanama Kawi, Padmasusastra, 1897, #18.', 5),
(2929, 'Dhuwit', 'D huwit (DuwIt) : ardana | arta | hartawan | uwang | d anardana | kopang | topang | sadana | yatra. Dasanama Kawi, Padmasusastra, 1897, #18.', 7),
(2930, 'dêne', 'd êne (d|ne) : d ênèkke (Tg.) d uwèkke. Javaansche Woordenlijst, De Nooy, 1893, #24.', 10),
(2931, 'daning', 'd aning (daniG) : têgal (Pm.) d ening = lo. Javaansche Woordenlijst, De Nooy, 1893, #24.', 6),
(2932, 'dawaka', 'd awaka () : d rêsba Tg. Javaansche Woordenlijst, De Nooy, 1893, #24.', 1),
(2933, 'drêmis', 'd rêmis (dr|mIs) : Bs., (Pb.) anggranyah. bocah an = anggranyah: pêlêm mêntah d ipangan. Javaansche Woordenlijst, De Nooy, 1893, #24.', 4),
(2934, 'dêgrêg', 'd êgrêg (d|gr|g) : mujur = bêgja Pc. nanging mung tumrap wong ngabotohan. kaya ta: Si Surajaya olèhe sêtotêr d êdrêg = mujur = bêgja, sawêngi ngukupi bae. Javaansche Woordenlijst, De Nooy, 1893, #24.', 5),
(2935, 'dodok', 'd odok (dOdO?) : d uduk Mgl. lakumu d odokên = d udukên saka kene bae. Javaansche Woordenlijst, De Nooy, 1893, #24.', 5),
(2936, 'dewa', 'd ewa () : d ewan, andèrès, Ng. (Kb.). Javaansche Woordenlijst, De Nooy, 1893, #24.', 7),
(2937, 'dalèr', 'd alèr (dalEr) : an: anggili = asêlur, Tg. wong d esa kang malêbu grêbêg andêlèr = anggili = asêlur. Javaansche Woordenlijst, De Nooy, 1893, #24.', 6),
(2938, 'dèlèk', 'd èlèk (dElE?) : an (Bn.) andokok. têmbung d èlèk mèmpêr saka rimbaganing têmbung d èlèh. Javaansche Woordenlijst, De Nooy, 1893, #24.', 10),
(2939, 'dolèk', 'd olèk (dolE?) : (Bn.) d uwèk = d uwe. d olèkku = d uwèkku. Javaansche Woordenlijst, De Nooy, 1893, #24.', 7),
(2940, 'dêlèp', 'd êlèp (d|lEp) : (Ws.) d êlap (Kr.) andablêg. Javaansche Woordenlijst, De Nooy, 1893, #24.', 3),
(2941, 'dlamong', 'd lamong (dlamOG) : andêlamong (Tg.) nglantur. (Pb.) tadhah, bocah cilik d êlamonge = tadhahe akèh. Javaansche Woordenlijst, De Nooy, 1893, #24.', 9),
(2942, 'dipuna', 'd ipuna () : (Tg.) cikbèn, manawa saka rusaking têmbung akdèkpuna, d adi: d ipuna. Javaansche Woordenlijst, De Nooy, 1893, #24.', 1),
(2943, 'doplèti', 'd oplèti (doplEti) : (Pb.) d ititèni. manawa saka têmbung Walănda: opletten. Javaansche Woordenlijst, De Nooy, 1893, #24.', 4),
(2944, 'deyan', 'd eyan () : Tg., Pm., bokmanawa = rak, Pb., (B.) kira = d uga = watara. Javaansche Woordenlijst, De Nooy, 1893, #24.', 3),
(2945, 'dimok', 'd imok (dimO?) : d imokna, (Bn.) cikbèn. Javaansche Woordenlijst, De Nooy, 1893, #24.', 2),
(2946, 'dêkêm', 'd êkêm (d|k|m) : cêkêl, Ng., (Kb.) Kr., (Bg.) ing Sk. ora nganggo têmbung d imèk, kang d ianggo d êmak, d êmèk sarta d êmok. Javaansche Woordenlijst, De Nooy, 1893, #24.', 10),
(2947, 'dumbêg', 'd umbêg (dumb|g) : (Bl.) clorot, araning panganan. wadhahe janur d iblêngkêrake, ing pucuk cilik laya d rêmênan janur, d iisèni galêpung karo gula. Javaansche Woordenlijst, De Nooy, 1893, #24.', 1),
(2948, 'dobal', 'd obal () : (Tg.) d rêmba. Javaansche Woordenlijst, De Nooy, 1893, #24.', 5),
(2949, 'dingar', 'd ingar (diGar) : Kr., (Bg.) tumênga. manawa saka rusaking têmbung d hangar, d adi d ingar. Javaansche Woordenlijst, De Nooy, 1893, #24.', 1),
(2950, 'dêngok', 'd êngok (d|GO?) : d êlok, Bn. ing Sk. ora nganggo têmbung d êngok, nanging nganggo têmbung d êngongok. Javaansche Woordenlijst, De Nooy, 1893, #24.', 3),
(2951, 'dhandhêng', 'd handhêng (DanD|G) : andhadhêng (B.) ambêlayang. (in Wdb = mlancong) zie d hangdhêng Corr. Javaansche Woordenlijst, De Nooy, 1893, #24.', 8),
(2952, 'dhuwik', 'd huwik (DuwI?) : (Bn.) d huwit. Javaansche Woordenlijst, De Nooy, 1893, #24.', 5),
(2953, 'dhèlêt', 'd hèlêt (DEl|t) : Sm. (M.) d hela, sa = sadhela. Javaansche Woordenlijst, De Nooy, 1893, #24.', 2),
(2954, 'dhèdhèk', 'd hèdhèk (DEDEk) : (Pm.) d hedhe. Javaansche Woordenlijst, De Nooy, 1893, #24.', 3),
(2955, 'dhêmanakake', 'd hêmanakake (D|manakake) : (Kb.) d êmênakake. Javaansche Woordenlijst, De Nooy, 1893, #24.', 10),
(2956, 'dhamplèng', 'd hamplèng (DamplEG) : (Pb.) d hapur. d amplèngmu singkalanên. Javaansche Woordenlijst, De Nooy, 1893, #24.', 2),
(2957, 'dhèg', 'd hèg (DEg) : Mgl., Kb., (Holl. d ek, d eken ? Corr) kamli = salimut, nanging têmbung karo pisan ?, iya iku kêmul. Javaansche Woordenlijst, De Nooy, 1893, #24.', 7),
(2958, 'dhaglêng', 'd haglêng (Dagl|G) : (Tm.) d hangling, vgl. Wdb. d hêglêng, Corr. Javaansche Woordenlijst, De Nooy, 1893, #24.', 1),
(2959, 'dhèngèn', 'd hèngèn (DEGEn) : (Pm.) d hangan. Javaansche Woordenlijst, De Nooy, 1893, #24.', 8),
(2960, 'dhangdhêng', 'd hangdhêng (DaGD|G) : mlancong C. vgl. d handhêng Corr. Javaansche Woordenlijst, De Nooy, 1893, #24.', 3),
(2961, 'diajoni', 'd iajoni (diajOni) : d icêdhaki sarana mlaku mêngarêp; d iajokake: d igawa ( d isodhokake lsp) mêngarêp; kc. maju, ajon, kêmajon. II (ut. ajo) êngg: aja. Bausastra Jawa, Poerwadarminta, 1939, #75.', 5),
(2962, 'amongdagang', 'among d agang (amOG dagaG) : kn. ak d êdagangan, sudagar. Bausastra Jawa, Poerwadarminta, 1939, #75.', 5),
(2963, 'angindharat', 'angin d harat (aGin Darat) : kn angin kang pinangkane saka ing d haratan. Bausastra Jawa, Poerwadarminta, 1939, #75.', 10),
(2964, 'angkatandharat', 'angkatan d harat (aGkatan Darat) : kn prajurit d haratan. Bausastra Jawa, Poerwadarminta, 1939, #75.', 5),
(2965, 'bale-desa', 'bale- d esa (bale­desO) : kn omah d arbèking d esa d ianggo pakumpulan. Bausastra Jawa, Poerwadarminta, 1939, #75.', 9),
(2966, 'banyak-dhalang', 'banyak- d halang (ba¥a?­DalaG) : kn. ar. upacara wadhah d ipêtha banyak (êmas, slaka). Bausastra Jawa, Poerwadarminta, 1939, #75.', 5),
(2967, 'cukit-dulit', 'cukit- d ulit (cukIt­dulIt) : kn. 1 (wong adol trasi) wong asor, nistha; 2 pc. wong d adi rowanging maling. Bausastra Jawa, Poerwadarminta, 1939, #75.', 2),
(2968, 'cucukdhandhang', 'cucuk d handhang (cucU? DanDaG) : kn. ar. piranti d ianggo nyigar watu lsp. awujud wêsi d igarani, ing kiwa têngêne lancip. Bausastra Jawa, Poerwadarminta, 1939, #75.', 7),
(2969, 'dablag', 'd ablag () : kn d abag. Bausastra Jawa, Poerwadarminta, 1939, #75.', 7),
(2970, 'dadèk', 'd adèk (dadE?) : n-[x] gêni n, n-[x] latu k gawe gêni; kc. d adi, d adèn. Bausastra Jawa, Poerwadarminta, 1939, #75.', 10),
(2971, 'daerah', 'd aerah () : êngg. kn 1 wêwêngkon, tlatah; 2 wawasaning panêmu (pangrêmbug); kc. d erah. Bausastra Jawa, Poerwadarminta, 1939, #75.', 3),
(2972, 'dagêl', 'd agêl (dag|l) : êngg. kn d hagêl. Bausastra Jawa, Poerwadarminta, 1939, #75.', 1),
(2973, 'dahpuna', 'd ahpuna (dahpunO) : prik. d ahgene. Bausastra Jawa, Poerwadarminta, 1939, #75.', 9),
(2974, 'dahuru', 'd ahuru () : kn. ak kc. d auru. Bausastra Jawa, Poerwadarminta, 1939, #75.', 3),
(2975, 'dayita', 'd ayita (dayitO) : prik. d ayinya. Bausastra Jawa, Poerwadarminta, 1939, #75.', 8),
(2976, 'daknang', 'd aknang (da?naG) : prik. d ak­mênang. Bausastra Jawa, Poerwadarminta, 1939, #75.', 9),
(2977, 'dakwa', 'd akwa (da?wO) : (A) kn 1 panêrka; 2 wong kang d igugat ( d ipriksa prakarane); d i-[x]: d itêrka, d iarani nglakoni ala (nyolong lsp). Bausastra Jawa, Poerwadarminta, 1939, #75.', 7),
(2978, 'dal', 'd al () : d ipun-[x]-akên pc. k d iwêtokake. Bausastra Jawa, Poerwadarminta, 1939, #75.', 6),
(2979, 'dalah', 'd alah () : I (ut. [x] kn 1 lan uga: 2 karo, sarta (kabèh katut kalêbu). II d i-[x] êngg. kn: d isèlèh(-ake). Bausastra Jawa, Poerwadarminta, 1939, #75.', 2),
(2980, 'dalit', 'd alit (dalIt) : d i-[x] kn 1 d irapêtake ( d itambal) sarana d ilèrèki d hêmpul, patri, lêmpung lsp; 2 pc. d igêmèni bangêt, d iirit-irit bangêt pangane. Bausastra Jawa, Poerwadarminta, 1939, #75.', 1),
(2981, 'dama', 'd ama (dOmO) : I kw 1 asor, nistha; 2 bodho. II d i-[x]-[x] kw: 1 d iugung, d iuja ing sapanjaluke (saking trêsnane); 2 d iaji-aji; kc. d ên. Bausastra Jawa, Poerwadarminta, 1939, #75.', 4),
(2982, 'damèn', 'd amèn (damEn) : kn wit pari (garing); kc. d ami. Bausastra Jawa, Poerwadarminta, 1939, #75.', 3),
(2983, 'damêl', 'd amêl (dam|l) : k gawe; d ê k: gêgaman. Bausastra Jawa, Poerwadarminta, 1939, #75.', 4),
(2984, 'dana bau', 'd ana bau (dOnO bau) : kn d êdana sarana nyambutgawe tanpa pituwas. Bausastra Jawa, Poerwadarminta, 1939, #75.', 8),
(2985, 'dana-driyah', 'd ana- d riyah (dOnO­driyah) : kn nindakake kautaman sarana d êdana. Bausastra Jawa, Poerwadarminta, 1939, #75.', 1),
(2986, 'danawira', 'd anawira (dOnOwirO) : (S) kw. ak wong kang sênêng d êdana. Bausastra Jawa, Poerwadarminta, 1939, #75.', 1),
(2987, 'danta', 'd anta (dantO) [Cs2] : I (S) kw untu, gadhing; cs. 2 kc. d ênta. II (S) kw. ak: sarèh, alon, lirih. Bausastra Jawa, Poerwadarminta, 1939, #75.', 2),
(2988, 'dantên', 'd antên (dant|n) : êngg. k d ara. Bausastra Jawa, Poerwadarminta, 1939, #75.', 5),
(2989, 'dangdanan', 'd angdanan (daGdanan) : êngg. kn d andanan. Bausastra Jawa, Poerwadarminta, 1939, #75.', 1),
(2990, 'daugan', 'd augan () : êngg. kn d êgan. Bausastra Jawa, Poerwadarminta, 1939, #75.', 7),
(2991, 'dara', 'd ara (dOrO) : I kn ar. manuk bngs. d êruk, putêr lsp. tapak [x]: 1 ar. têtuwuhan; 2 cagaking gêdêbog kêlir wayang; 3 ar. caraning ngênam ut. ngglamit (tumpang-tumpangan mrapat). II (n) kn: wc. bêndara. III êngg. kn: bumbung pandèrèsan. IV (S) kw. ak: bojo, prawan. Bausastra Jawa, Poerwadarminta, 1939, #75.', 8),
(2992, 'darak', 'd arak (dara?) : ( d i-)[x]-i pc. d iarani ( d isêngguh, d ikira). Bausastra Jawa, Poerwadarminta, 1939, #75.', 5),
(2993, 'daran', 'd aran () : prik. d arak. Bausastra Jawa, Poerwadarminta, 1939, #75.', 7),
(2994, 'darana', 'd arana (darOnO) : (S) kw. 1 kukuh, sêntosa; 2 sabar; kc. d rana. Bausastra Jawa, Poerwadarminta, 1939, #75.', 6),
(2995, 'darma', 'd arma (darmO) : I (S) kw. ak1 kawajiban, kautaman, panggawe bêcik; 2 wêwarah, anggêr-anggêr; 3 papan suci, candhi, kuburan. II kn. ( d armi k.ak) 1 (ut. sa-[x]) nindakake apa-apa mung marga nêtêpi kawajibane; 2 panjurung (pasumbang) saèm. d ana; d ini: d iwènèhi d arma; d idarmakake: d idanakake; kc. d êrma, sadêrma. ... selengkapnya d arma (darmO) : I (S) kw. ak1 kawajiban, kautaman, panggawe bêcik; 2 wêwarah, anggêr-anggêr; 3 papan suci, candhi, kuburan. II kn. ( d armi k.ak) 1 (ut. sa-[x]) nindakake apa-apa mung marga nêtêpi kawajibane; 2 panjurung (pasumbang) saèm. d ana; d idarmani: d iwènèhi d arma; d idarmakake: d idanakake; kc. d êrma, sadêrma. III kw: bapa; kc. sudarma. Bausastra Jawa, Poerwadarminta, 1939, #75.', 10),
(2996, 'darmaja', 'd armaja (darmOjO) : (S) kw. ak turuning wong utama, d arah lsp. Bausastra Jawa, Poerwadarminta, 1939, #75.', 6),
(2997, 'darpaya', 'd arpaya (darpOyO) : kw kc. d arpa. Bausastra Jawa, Poerwadarminta, 1939, #75.', 10),
(2998, 'darwya', 'd arwya (darwyO) : kw. ak: d uwe. Bausastra Jawa, Poerwadarminta, 1939, #75.', 7),
(2999, 'datullah', 'd atullah (datulah) : (A) kn d ating Allah. Bausastra Jawa, Poerwadarminta, 1939, #75.', 5),
(3000, 'dawêg', 'd awêg (daw|g) : I êngg. kn 1 wis tutug, wis katog; 2 sêdhêngan; d i-[x]-ake; d ikatogake. II k. ak: lagi. III pc. êngg: ayo, ênya, mara! Bausastra Jawa, Poerwadarminta, 1939, #75.', 5),
(3001, 'dawêgan', 'd awêgan (daw|gan) : êngg. kn d êgan. Bausastra Jawa, Poerwadarminta, 1939, #75.', 9),
(3002, 'de', 'd e () : I kw 1 ak.gawe; 2 d ene; 3 d ening. II êngg. n: d i-. III (nde) êngg. pc: d uwe. Bausastra Jawa, Poerwadarminta, 1939, #75.', 10),
(3003, 'debagan', 'd ebagan () : pc nggolang-nggoling jêmpalikan (marga sayah lsp); kc. d eblag, gêdebag. Bausastra Jawa, Poerwadarminta, 1939, #75.', 3),
(3004, 'deblag', 'd eblag () : n-[x] pc katon jêmbar sarta sêntosa tmr. d hadha; d i-[x], d idhèblêg êngg. kn: 1 d igablog; 2 d ipopok ( d iurug) tmr. galêngan lsp. Bausastra Jawa, Poerwadarminta, 1939, #75.', 10),
(3005, 'deyane', 'd eyane () : prik. d eyan. Bausastra Jawa, Poerwadarminta, 1939, #75.', 10),
(3006, 'dèk', 'd èk (dE?) : I êngg. pc sangka; kc. ka, kadi. II [x]-e (-ku, -mu) êngg. pc: d uwèke (-ku, -mu). Bausastra Jawa, Poerwadarminta, 1939, #75.', 2),
(3007, 'dèkèng', 'd èkèng (dEkEG) : awak [x] pc awakku, aku d hewe. Bausastra Jawa, Poerwadarminta, 1939, #75.', 6),
(3008, 'dèlèh', 'd èlèh (dElEh) : d i-[x] êngg. kn d isèlèh, d idokok. Bausastra Jawa, Poerwadarminta, 1939, #75.', 2),
(3009, 'dèlèp', 'd èlèp (dElEp) : I n-[x] êngg. kn 1 ndhèwèki; 2 nekad; 3 takad. II d i-[x]-i êngg. kn: d idhèdhèki. Bausastra Jawa, Poerwadarminta, 1939, #75.', 9),
