(3217, 'dhag', 'd hag (Dag) : êngg. kn 1 têlag, têndhang; 2 lowong (ora mlêbu ing panggawean, tungguk lsp); d i-[x]-ake êngg. pc: 1 d isuwungake (tmr. omah lsp); d ilowongi (tmr pagawean). Bausastra Jawa, Poerwadarminta, 1939, #75.', 1),
(3218, 'dhagdhag', 'd hagdhag (DaDag) : d i-[x]-ake pc d iêblak-êblakake; kc. d hag. Bausastra Jawa, Poerwadarminta, 1939, #75.', 5),
(3219, 'dhah', 'd hah (Dah) : (n) (W) pc taklim (yèn kêpêthuk lsp); d i-ndhahi pc. d itaklimi. Bausastra Jawa, Poerwadarminta, 1939, #75.', 6),
(3220, 'dhahga', 'd hahga (DahgO) : kw 1 ngêlak; 2 murka ngangsa-angsa; kc. d haga. Bausastra Jawa, Poerwadarminta, 1939, #75.', 7),
(3221, 'dhahyang', 'd hahyang (DahyaG) : êngg. pc. d hayang. Bausastra Jawa, Poerwadarminta, 1939, #75.', 2),
(3222, 'dhayang', 'd hayang (DayaG) : prik. d hahyang. Bausastra Jawa, Poerwadarminta, 1939, #75.', 5),
(3223, 'dhayuh', 'd hayuh (DayUh) : pc êngg. d hayoh. Bausastra Jawa, Poerwadarminta, 1939, #75.', 9),
(3224, 'dhayum', 'd hayum (DayUm) : êngg. kn wis d ilêrêmake supaya kêlêbon hawa (tmr. lêmah kang d igarap); kc. d hayung. Bausastra Jawa, Poerwadarminta, 1939, #75.', 5),
(3225, 'dhayot', 'd hayot (DayOt) : êngg. knkukul; d heyot. Bausastra Jawa, Poerwadarminta, 1939, #75.', 10),
(3226, 'dhak', 'd hak (Da?) : I (n) êngg. n ora. II (ndhak) pc: mundhak, up. aja nakal, ndhak d isrêngêni. III (ndhak ene) pc: pêndhake d ina (sasi lsp) iki. IV d ipun-[x]-akên pc: d ipun-êdhak-akên; kc. udhun. V d i-ndhakake pc: d iêndhakake; kc. êndhak. Bausastra Jawa, Poerwadarminta, 1939, #75.', 9),
(3227, 'dhakên', 'd hakên (Dak|n) : d ipun-[x] êngg. k. d idhaku. Bausastra Jawa, Poerwadarminta, 1939, #75.', 1),
(3228, 'dhak-wa', 'd hak-wa (Da?­wO) : (ndhakwa) kn. sing siji cêndhak sijine d hawa. Bausastra Jawa, Poerwadarminta, 1939, #75.', 3),
(3229, 'dhalangan', 'd halangan (DalaGan) : kn. saèm meja ut. d hingklik d awa d ianggo nyèlèhake kayu sing d ipasah (apa-apa sing d igarap); êngg. awak-awaking graji, raganganing pit. Bausastra Jawa, Poerwadarminta, 1939, #75.', 7),
(3230, 'dham', 'd ham (Dam) : I êngg. kn. giliran (jaga ing cakruk). II êngg. kn: bêndhungan. III ([x]-[x]-an) kn: ar. d olanan nganggo blabag lsp. d igambari pêsagèn-pêsagèn (abang putih ut. irêng putih). Bausastra Jawa, Poerwadarminta, 1939, #75.', 9),
(3231, 'dharmaga', 'd harmaga (DarmOgO) : jk. d alan gêdhe. Bausastra Jawa, Poerwadarminta, 1939, #75.', 7),
(3232, 'dhambul', 'd hambul (DambUl) : kn. ar. d olanan sarana ngumbul-umbulake watu ut. bal. Bausastra Jawa, Poerwadarminta, 1939, #75.', 9),
(3233, 'dhampak', 'd hampak (Dampa?) : êngg. kn jêmbar d hadhane lan sêmbada (tmr. pawakan). Bausastra Jawa, Poerwadarminta, 1939, #75.', 9),
(3234, 'dhampyak', 'd hampyak (Dampya?) : [x]-[x], d hêan kn mlaku barêng jèjèr-jèjèr. Bausastra Jawa, Poerwadarminta, 1939, #75.', 9),
(3235, 'dhampyang', 'd hampyang (DampyaG) : I [x]- [x] pc d hampyak- d hampyak. II kn.: rangkêp gêgandhengan, kc. sagantilan ana wohe 3 ut. luwih; d i-[x] pc: d igandhèng d adi siji, d irajut; [x]-an: ombyokan, d hompolan. Bausastra Jawa, Poerwadarminta, 1939, #75.', 1),
(3236, 'dhampyuk', 'd hampyuk (DampyU?) : pc d humpyukan. Bausastra Jawa, Poerwadarminta, 1939, #75.', 9),
(3237, 'dhampyung', 'd hampyung (DampyUG) : kn d hampyang. Bausastra Jawa, Poerwadarminta, 1939, #75.', 2),
(3238, 'dhamplak', 'd hamplak (Dampla?) : (ut. [x]-[x]) kn gêdhe d awa (tmr. sungu, asêm, gêdhang). Bausastra Jawa, Poerwadarminta, 1939, #75.', 3),
(3239, 'dhangak', 'd hangak (DaGa?) : n-[x] kn êndhase nglênggak munggah raine tumênga; kc. d hêngak. Bausastra Jawa, Poerwadarminta, 1939, #75.', 4),
(3240, 'dhang-dheng', 'd hang- d heng (DaG­DEG) : kc tansah nyuwara mak d hêng. Bausastra Jawa, Poerwadarminta, 1939, #75.', 5),
(3241, 'dhangêt', 'd hangêt (DaG|t) : d i-[x]-ake êngg. kn d irungokake; kc. mi. Bausastra Jawa, Poerwadarminta, 1939, #75.', 8),
(3242, 'dhangbyang', 'd hangbyang (DaGbyaG) : kw 1 sêsêbutane para pandhita; d hêmit kang mbaurêksa; kc. d hanyang. Bausastra Jawa, Poerwadarminta, 1939, #75.', 1),
(3243, 'dhangyang', 'd hangyang (DaGyaG) : prik. d hangbyang. Bausastra Jawa, Poerwadarminta, 1939, #75.', 7),
(3244, 'dhangir', 'd hangir (DaGIr) : kn maculi lêmah ( d iadhuk sarta d irêsiki rêrêgêde); [x] alis br: kêrik alis; d i-[x]: d ipaculi ( d iadhuk sarta d irêsiki rêrêgêde). Bausastra Jawa, Poerwadarminta, 1939, #75.', 5),
(3245, 'dhangkak', 'd hangkak (DaGka?) : êngg. kn. ak gulune cêndhak sarta d hadhane mungal; 2 kc. d hêngkak. Bausastra Jawa, Poerwadarminta, 1939, #75.', 6),
(3246, 'dhangkèl', 'd hangkèl (DaGkEl) : kn oyot lajêr sing mbêdhênggol; d i-[x]: d ibêdhol ( d ikêdhuki) d hangkèle; n-[x] êngg.ak: tanpa mung mangan oyod-oyodan. Bausastra Jawa, Poerwadarminta, 1939, #75.', 8),
(3247, 'dhangklak-dhangklik', 'd hangklak- d hangklik (DaGkla?­DaGklI?) : kn. ak d hêngklak- d hêngklik. Bausastra Jawa, Poerwadarminta, 1939, #75.', 10),
(3248, 'dhangkrok', 'd hangkrok (DaGkrO?) : prik. d hangkruk. Bausastra Jawa, Poerwadarminta, 1939, #75.', 6),
(3249, 'dhauk', 'd hauk (DaU?) : pc wis tuwa bangêt; kc. d hawuk. Bausastra Jawa, Poerwadarminta, 1939, #75.', 3),
(3250, 'dhaulu', 'd haulu (Daulu) : kn. ak 1 ula êndhase loro (mung ing d ongèng); 2 atine mangro; gunêman krama karo ngoko d icampur baè. Bausastra Jawa, Poerwadarminta, 1939, #75.', 6),
(3251, 'dhaos', 'd haos (DaOs) : êngg. k d hacin. Bausastra Jawa, Poerwadarminta, 1939, #75.', 2),
(3252, 'dhapuk', 'd hapuk (DapU?) : d i-[x] kn 1. ak. d itumpuk pêpanthan (tmr. pari sing mêntas d iênèni); 2. d itata sarta d irancang (tmr. prakara sing arêp d irêmbug, crita, buku lsp), [x]-an: 1. êngg.pc.pêpanthan, tumpukan; 2. rancangan, tatananing crita, layang lsp. Bausastra Jawa, Poerwadarminta, 1939, #75.', 3),
(3253, 'dhar', 'd har (Dar) : d i-[x]-ake pc d iwêake. Bausastra Jawa, Poerwadarminta, 1939, #75.', 6),
(3254, 'dharah', 'd harah (Darah) : êngg. kn 1 d arah; 2 pc. gêtih; [x] mudha pc: wêwatakane wong nom gampang kêbrangas, ora sabaran. Bausastra Jawa, Poerwadarminta, 1939, #75.', 6),
(3255, 'dhar-dhèr', 'd har- d hèr (Dar­DEr) : pc tansah nyuwara d hèr (mêrcon, bêdhil lsp). Bausastra Jawa, Poerwadarminta, 1939, #75.', 7),
(3256, 'dhasèn', 'd hasèn (DasEn) : kn nganggo d hasi. Bausastra Jawa, Poerwadarminta, 1939, #75.', 6),
(3257, 'dhatêngan', 'd hatêngan (Dat|Gan) : êngg. k d hayoh. Bausastra Jawa, Poerwadarminta, 1939, #75.', 1),
(3258, 'dhatulaya', 'd hatulaya (DatulOyO) : kw d alêming ratu, kêdhaton. Bausastra Jawa, Poerwadarminta, 1939, #75.', 5),
(3259, 'dhawahan', 'd hawahan (Dawahan) : êngg. k d hawuhan (bêndungan). Bausastra Jawa, Poerwadarminta, 1939, #75.', 7),
(3260, 'dhawoh', 'd hawoh (DawOh) : êngg. kn: tiba; kc. d hawuh. Bausastra Jawa, Poerwadarminta, 1939, #75.', 9),
(3261, 'dhebat', 'd hebat (Debat) : (W) kn pêpadon arêbut bênêr (ana ing pakumpulan lsp); d i-[x]: d ipadoni; [x]- [x]-an: pêpadon arêbut bênêring panêmu. Bausastra Jawa, Poerwadarminta, 1939, #75.', 8),
(3262, 'dhèblèng', 'd hèblèng (DEblEG) : (-an) kn d hablang mêmburi rada nyongat munggah (tmr. sungu, sinthingan ikêt). Bausastra Jawa, Poerwadarminta, 1939, #75.', 7),
(3263, 'dhèdhèl-dhowèl', 'd hèdhèl- d howèl (DEDEl­DowEl) : pc êntèk-êntèkan d huwite (sandhang panganggone). Bausastra Jawa, Poerwadarminta, 1939, #75.', 8),
(3264, 'dhèdhèr', 'd hèdhèr (DEDEr) : d i-[x]-(ake) kn. ak d ibèbèr, d iêgarake (tmr. swiwi lsp). Bausastra Jawa, Poerwadarminta, 1939, #75.', 7),
(3265, 'dhèdhès', 'd hèdhès (DEDEs) : kn ar. wêwangi sing asal saka klênjar rase; kc: d hidhis, kaan. Bausastra Jawa, Poerwadarminta, 1939, #75.', 6),
