(4895, 'gada', 'g ada (gOdO) : g ada. Têmbung Kawi Mawi Têgêsipun, Wintêr, 1928, #1506.', 1),
(4896, 'gada-gadan', 'g ada- g adan (gOdO­gadan) : g êpah- g êpah, g ada- g inada, pupuh-pinupuh. Têmbung Kawi Mawi Têgêsipun, Wintêr, 1928, #1506.', 5),
(4897, 'guwa', 'g uwa (guwO) : g uwa. Têmbung Kawi Mawi Têgêsipun, Wintêr, 1928, #1506.', 8),
(4898, 'gila', 'g ila (gilO) : ajrih, g ila, edan, agêng. Têmbung Kawi Mawi Têgêsipun, Wintêr, 1928, #1506.', 5),
(4899, 'galar', 'g alar () : dhasar, g alar. Têmbung Kawi Mawi Têgêsipun, Wintêr, 1928, #1506.', 6),
(4900, 'gêlar', 'g êlar (g|lar) : wontên, g êlar, g umêlar, tata, tingkah. Têmbung Kawi Mawi Têgêsipun, Wintêr, 1928, #1506.', 7),
(4901, 'gêlaran', 'g êlaran (g|laran) : g êlaran, panata. Têmbung Kawi Mawi Têgêsipun, Wintêr, 1928, #1506.', 8),
(4902, 'gêlap', 'g êlap (g|lap) : g êlap, bandhêm, jêbrèd. Têmbung Kawi Mawi Têgêsipun, Wintêr, 1928, #1506.', 9),
(4903, 'gêlang', 'g êlang (g|laG) : g êlang, bêndu, sumorot. Têmbung Kawi Mawi Têgêsipun, Wintêr, 1928, #1506.', 9),
