(12986, 'rajung', 'r ajung (rajUG) : r ajungan (araning iwak sêgara). Bausastra: Jarwa Kawi, Padmasusastra, 1903, #11.', 5),
(12987, 'rayap', 'r ayap () : astaki, layap, dhudhuk; [ngrayap]: masulung-sulung; [ r atuning r ayap]: gundhik; [kaya r ayap]: masulung. Bausastra: Jarwa Kawi, Padmasusastra, 1903, #11.', 1),
(12988, 'reyong', 'r eyong (reyOG) : [ r eyong- r eyongan]: r êrêncêngan, r uruncangan. Bausastra: Jarwa Kawi, Padmasusastra, 1903, #11.', 6),
(12989, 'rum', 'r um (rUm) : [= a]: r êsmi, sumrêg; [arum-arum]: r um- r um; [ngungrum]: êla-êla; [pangungrum]: hakung, r u-mrum. Bausastra: Jarwa Kawi, Padmasusastra, 1903, #11.', 4),
(12990, 'romah', 'r omah () : [ngromahi]: r ambuti. Bausastra: Jarwa Kawi, Padmasusastra, 1903, #11.', 9),
(12991, 'rêmak', 'r êmak (r|ma?) : r ênyuh, r ênyêk, r impêk, trênyuh; [ng]: sumyuh. Bausastra: Jarwa Kawi, Padmasusastra, 1903, #11.', 3),
(12992, 'rêmêk', 'r êmêk (r|m|k) : nwuh, cur, cêrêh, curna, curni, r êncêm, r uk, r usak, r êmus, r êmpu, r êmpuh, r êmpak, r ug, r êngka, danaga, dadaka, tannyu, tênnyuh, trênnyuh, suwa, syuh, parêpêh, pitundha, pyuh, mêh, gêrêm, gityês, gyuh; [ng]: r umêncêm, r umênyêk, r umêmpuh, r umêmpak, mangrêncêm, ngramês, ngaramês, ngrêmpuh, ... selengkapnya r êmêk (r|m|k) : nwuh, cur, cêrêh, curna, curni, r êncêm, r uk, r usak, r êmus, r êmpu, r êmpuh, r êmpak, r ug, r êngka, danaga, dadaka, tannyu, tênnyuh, trênnyuh, suwa, syuh, parêpêh, pitundha, pyuh, mêh, gêrêm, gityês, gyuh; [ngrêmêk]: r umêncêm, r umênyêk, r umêmpuh, r umêmpak, mangrêncêm, ngramês, ngaramês, ngrêmpuh, ngrêmpak, ngrêmpêk, ngrimpêk; [ngrêmêki]: pangrêncêmi. Bausastra: Jarwa Kawi, Padmasusastra, 1903, #11.', 9),
(12993, 'rêmuk', 'r êmuk (r|mU?) : curna, r ahêk, r ênyuh, r êmak, r êmêk, r êmuk, r êmpu, r êmpuh, r impêk, swuh; [ r êan]: r êrêmpon; [ngrêmuk]: r umahêk, r umêmpuh, r umêmuk, sumwuh, ngrêmpuh, ngrimpêk. Bausastra: Jarwa Kawi, Padmasusastra, 1903, #11.', 10),
(12994, 'rêmêd', 'r êmêd (r|m|d) : ura, cêcêh, r amês; [ r êmêdan]: r amêsan; [ng]: r umamês, mangura, ngura; [ r inêmêd]: cinêmêd. Bausastra: Jarwa Kawi, Padmasusastra, 1903, #11.', 2),
(12995, 'ramês', 'r amês (ram|s) : tigas; [ r amêsan]: tigasan. Bausastra: Jarwa Kawi, Padmasusastra, 1903, #11.', 7),
