(13578, 'rumah', 'r umah () : di-[x]-i kn: diombèri, disudhiyani papan; [x]-an: klowongan, papan sing disêdhiyakake, sadhiyan; kc. r omah. Bausastra Jawa, Poerwadarminta, 1939, #75.', 3),
(13579, 'rumah-makan', 'r umah-makan (rumah­makan) : (M) kn: r êstoran. Bausastra Jawa, Poerwadarminta, 1939, #75.', 6),
(13580, 'rumakêt', 'r umakêt (rumak|t) : kn: sumanak bangêt; kc. r akêt. Bausastra Jawa, Poerwadarminta, 1939, #75.', 9),
(13581, 'rumambas', 'r umambas () : kn: mbrabas têmbus tmr. banyu; kc. r ambas. Bausastra Jawa, Poerwadarminta, 1939, #75.', 4),
(13582, 'rumanti', 'r umanti () : n. r umantos k: 1 wis miranti, wis sêdhiya; 2 tata-tata, sumadhiya. Bausastra Jawa, Poerwadarminta, 1939, #75.', 5),
(13583, 'rumancaka', 'r umancaka (rumancOkO) : kw: njalari susah (kangelan); kc. r ancaka. Bausastra Jawa, Poerwadarminta, 1939, #75.', 7),
(13584, 'rumangsa', 'r umangsa (rumOGsO) : n. r umaos k: 1 wis krasa sajroning ati, mangrêti; 2 wis ngakoni salahe lsp; ngni: wis r umangsa; kc. r asa. Bausastra Jawa, Poerwadarminta, 1939, #75.', 1),
(13585, 'rumangsang', 'r umangsang (rumaGsaG) : kw: nggayuh, ngranggèh, ngrangsang; kc. r angsang. Bausastra Jawa, Poerwadarminta, 1939, #75.', 3),
(13586, 'rumaup pada', 'r umaup pada (rumaUp pOdO) : kw: sujud nyungkêmi sikil; kc. r aup. Bausastra Jawa, Poerwadarminta, 1939, #75.', 10),
(13587, 'rumaras', 'r umaras () : I kw: miris, susah. II kw: bêcik, endah, sarwa tata; kc. r aras, laras. Bausastra Jawa, Poerwadarminta, 1939, #75.', 8),
(13588, 'rumasuk', 'r umasuk (rumasU?) : kn: mlêbu, manjing tmr. tamba lsp; kc. r asuk. Bausastra Jawa, Poerwadarminta, 1939, #75.', 5),
(13589, 'rumbuk', 'r umbuk (rumbU?) : êngg. kn: r ungkud, akèh thêthukulane. Bausastra Jawa, Poerwadarminta, 1939, #75.', 9),
(13590, 'rumbut', 'r umbut (rumbUt) : prik. r umbuk. Bausastra Jawa, Poerwadarminta, 1939, #75.', 8),
(13591, 'rumêgêp', 'r umêgêp (rum|g|p) : kw: nyandhak, nyêkêl gêgaman lsp; kc. r êgêp. Bausastra Jawa, Poerwadarminta, 1939, #75.', 5),
(13592, 'rumêksa', 'r umêksa (rum|ksO) : kn: njaga; kc. r êksa. Bausastra Jawa, Poerwadarminta, 1939, #75.', 5),
(13593, 'rumêmbês', 'r umêmbês (rum|mb|s) : br: ngêmbês, r êmbês. Bausastra Jawa, Poerwadarminta, 1939, #75.', 4),
(13594, 'rumêntah', 'r umêntah (rum|ntah) : k: r umuntuh, (tumiba). Bausastra Jawa, Poerwadarminta, 1939, #75.', 10),
(13595, 'rumêngkuh', 'r umêngkuh (rum|GkUh) : kn: bêcik pangrêngkuhe; kc. r êngkuh. Bausastra Jawa, Poerwadarminta, 1939, #75.', 8),
(13596, 'rumêsêp', 'r umêsêp (rum|s|p) : kn: 1 mlêbu ing (tmr. barang cuwèr lsp); 2 ngrêsêpake; kc. r êsêp. Bausastra Jawa, Poerwadarminta, 1939, #75.', 3),
(13597, 'rumyang', 'r umyang (rumyaG) : êngg. kn: r ame. Bausastra Jawa, Poerwadarminta, 1939, #75.', 7),
(13598, 'rumujag', 'r umujag () : kw: nggrujug; kc. r ujag. Bausastra Jawa, Poerwadarminta, 1939, #75.', 9),
(13599, 'rumuntuh', 'r umuntuh (rumuntUh) : n. r umêntah k: tumiba; kc. r untuh. Bausastra Jawa, Poerwadarminta, 1939, #75.', 3),
(13600, 'rumucat', 'r umucat () : kn: ucul panganggo; kc. r ucat. Bausastra Jawa, Poerwadarminta, 1939, #75.', 8),
(13601, 'rumpêk', 'r umpêk (rump|k) : prik. r umpak. Bausastra Jawa, Poerwadarminta, 1939, #75.', 5),
(13602, 'rumpaka', 'r umpaka (rumpOkO) : ng-[x] kn: 1 nyandra kalawan kêkidungan; 2 nganggit têmbang panyandra; r umpakan: 1 panyandra ing têmbang (kêkidungan); 2 têmbang, kidungan. Bausastra Jawa, Poerwadarminta, 1939, #75.', 2),
(13603, 'rumpi', 'r umpi () : kn: bngs. klambi jas kotang kanggo r angkêpan klambi jas bukak. Bausastra Jawa, Poerwadarminta, 1939, #75.', 7),
(13604, 'runa', 'r una (runO) : kw: r usak, pakewuh; kc. r unah. Bausastra Jawa, Poerwadarminta, 1939, #75.', 4),
(13605, 'runah', 'r unah () : kw: 1 r usak, pêcah, putung; 2 sêdhih, susah; ng-[x]: 1 ngrusak, mêcah; 2 nusahake. Bausastra Jawa, Poerwadarminta, 1939, #75.', 7),
(13606, 'rundah', 'r undah () : kw: sêdhih; kc. r udah. Bausastra Jawa, Poerwadarminta, 1939, #75.', 7),
(13607, 'rundha', 'r undha (runDO) : êngg. kn: nganglang ing wayah bêngi; kc. r ondha. Bausastra Jawa, Poerwadarminta, 1939, #75.', 2),
(13608, 'runtak', 'r untak (runta?) : êngg. kn: larahan, r êrêgêd ing lêmah. Bausastra Jawa, Poerwadarminta, 1939, #75.', 2),
(13609, 'runtang-runtung', 'r untang- r untung (runtaG­runtuG) : kn: tansah awor ora tau pisah (yèn mlaku lsp); kc. r untung. Bausastra Jawa, Poerwadarminta, 1939, #75.', 9),
(13610, 'runting', 'r unting (runtIG) : di-[x] kw: disuwèk, disuwir-suwir; kc. r ontang- r anting. Bausastra Jawa, Poerwadarminta, 1939, #75.', 8),
(13611, 'runtungan', 'r untungan (runtuGan) : êngg. kn: r ontogan. Bausastra Jawa, Poerwadarminta, 1939, #75.', 6),
(13612, 'runtyaka', 'r untyaka (runtyOkO) : kw. ak. sêrik, nêpsu; kc. r untik. Bausastra Jawa, Poerwadarminta, 1939, #75.', 4),
(13613, 'runcang-runcung', 'r uncang- r uncung (runcaG­runcuG) : kn: r untang- r untung, r untung- r untung, r êruntungan. Bausastra Jawa, Poerwadarminta, 1939, #75.', 3),
(13614, 'rêruncungan', 'r êruncungan (r|runcuGan) : prik. r uncang- r uncung. Bausastra Jawa, Poerwadarminta, 1939, #75.', 6),
(13615, 'runcat', 'r uncat () : kn: r ucat. Bausastra Jawa, Poerwadarminta, 1939, #75.', 7),
(13616, 'rungkêt', 'r ungkêt (ruGk|t) : êngg. pc: r ukêt. Bausastra Jawa, Poerwadarminta, 1939, #75.', 1),
(13617, 'rungsêb', 'r ungsêb (ruGs|b) : êngg. kn: angèl ambah-ambahane tmr. dalan; kc. r ubês. Bausastra Jawa, Poerwadarminta, 1939, #75.', 8),
(13618, 'rungsêg', 'r ungsêg (ruGs|g) : êngg. pc: r usak. Bausastra Jawa, Poerwadarminta, 1939, #75.', 5),
(13619, 'rupaka', 'r upaka (rupOkO) : kw: kc. r umpaka. Bausastra Jawa, Poerwadarminta, 1939, #75.', 7),
(13620, 'rurah', 'r urah () : kw: r usak, bubrah; mang-[x], ng-[x]: ngrusak. Bausastra Jawa, Poerwadarminta, 1939, #75.', 3),
(13621, 'rurêk', 'r urêk (rur|k) : kw: r ukêt tmr. pêrang; mang-[x], ng-[x]: ngrukêt, nêmpuh. Bausastra Jawa, Poerwadarminta, 1939, #75.', 2),
(13622, 'rusban', 'r usban (rUsban) : êngg. kn: r êsban. Bausastra Jawa, Poerwadarminta, 1939, #75.', 4),
(13623, 'rusêg', 'r usêg (rus|g) : êngg. kn: r êsêk. Bausastra Jawa, Poerwadarminta, 1939, #75.', 10),
(13624, 'ruci', 'r uci () : êngg. kn: r ingas, gampang nêpsune. Bausastra Jawa, Poerwadarminta, 1939, #75.', 10),
(13625, 'rucuh', 'r ucuh (rucUh) : êngg. kn: bngs. r ujak. Bausastra Jawa, Poerwadarminta, 1939, #75.', 5),
(13626, 'ruwag', 'r uwag () : [x]-[x] kn: ora tata; di-[x] êngg: dirucat, disêmploki; kc. r uwèg. Bausastra Jawa, Poerwadarminta, 1939, #75.', 7),
(13627, 'ruweda', 'r uweda (ruwedO) : kw: r ubeda, r êribêd. Bausastra Jawa, Poerwadarminta, 1939, #75.', 7),
(13628, 'ruwida', 'r uwida (ruwidO) : prik. r uweda. Bausastra Jawa, Poerwadarminta, 1939, #75.', 3),
(13629, 'ruwêd-rêntêng', 'r uwêd- r êntêng (ruw|d­r|nt|G) : kn: r êrêtu prakara sing njalari r êntênging nêgara lsp. Bausastra Jawa, Poerwadarminta, 1939, #75.', 5),
(13630, 'robat-rabèt', 'r obat- r abèt (robat­robEt) : prik. r obak- r abèk. Bausastra Jawa, Poerwadarminta, 1939, #75.', 5),
(13631, 'sulam', 's ulam [Ind] : I di: disulam, dibludir; s ulaman: bludiran, s ulaman. II wiji ut. bibit kanggo nyulami. Bausastra Indonesia-Jawi, Purwadarminta, c. 1939, #1979.', 5),
(13632, 'saudara', 's audara : et s udara , frère, allié, parent; ami. s udara wèdi , un ami fidèle. Dictionnaire Javanais-Français, L''Abbé P. Favre, 1870, #917.', 6),
(13633, 'sanès', 's anès : K. différemment, autrement: un autre. nyanès , s éparer, exclure. nyanèsakên , s éparer une chose d''une autre, rendre une chose différente d''une autre, établir une différence entre deux choses. Dictionnaire Javanais-Français, L''Abbé P. Favre, 1870, #917.', 7),
(13634, 'sawur', 's awur : N.K. l''action de parsemer, de répandre. nyawur , et nawur , s emer, parsemer, répandre; jeter de l''argent au
peuple. s umawur , s e répandre, s e disséminer. nyawuri ,
répandre s ur quelque chose, joncher une place. nyawurake , et nawurake , N. — kên , K. s emer ... selengkapnya s awur : N.K. l''action de parsemer, de répandre. nyawur , et nawur , s emer, parsemer, répandre; jeter de l''argent au peuple. s umawur , s e répandre, s e disséminer. nyawuri , répandre s ur quelque chose, joncher une place. nyawurake , et nawurake , N. — kên , K. s emer quelque chose; étendre une chose; rendre une chose publique. ka , parsemé; mêlé avec autre chose. Dictionnaire Javanais-Français, L''Abbé P. Favre, 1870, #917.', 2),
(13635, 'sêptèmbêr', 's êptèmbêr : s eptembre, le mois de s eptembre. Dictionnaire Javanais-Français, L''Abbé P. Favre, 1870, #917.', 9),
(13636, 'sayut', 's ayut : Kw. tenir, retenir, contenir: reculer; avoir une répugnance. nyayuti , et nayuti , N.K. s e modérer, s e retenir; retenir quelque chose, mettre obstacle à quelque chose. Dictionnaire Javanais-Français, L''Abbé P. Favre, 1870, #917.', 3),
(13637, 'sagêd', 's agêd : K. pouvoir, avoir la force, être en état; s avant, capable, habile, expert. s umagêd , s e montrer s avant; arrogant, présomptueux. nyagêdi , être en état de faire q.c. kaan , s avoir, s cience, habileté, capacité, talent. Dictionnaire Javanais-Français, L''Abbé P. Favre, 1870, #917.', 4),
(13638, 'sangkara', 's angkara : Kw. s auvage, cruel: colère: un cochon s auvage. — Kw. le s oleil. Dictionnaire Javanais-Français, L''Abbé P. Favre, 1870, #917.', 1),
(13639, 'saut', 's aut (saUt) : tampar, gawèl; [nyaut]: naut, nampar, s umahat, s umaut, manaut, manampar, mawrêgil, mawêgil; [nyauti]: nauti; [ s êan]: s aut; [panyaut]: panampar; [panyautan]: panamparan. Bausastra: Jarwa Kawi, Padmasusastra, 1903, #11.', 9),
(13640, 'sandi', 's andi () : rahsa, raasa, rahasya, lumad; [ s andi upaya]: s undopayasandi, s opaya; [ s andining]: pusthingi; [asandi]: masandi. Bausastra: Jarwa Kawi, Padmasusastra, 1903, #11.', 2),
(13641, 'sêntor', 's êntor (s|ntOr) : s êntor, basong. Bausastra: Jarwa Kawi, Padmasusastra, 1903, #11.', 4),
(13642, 'sêndhang', 's êndhang (s|nDaG) : s êndhang, s umbêr, warigi, wagiswara, lwah-lwah, prigi of parigi, botrawi, bilik, bèji; [nyêndhang]: marigi. Bausastra: Jarwa Kawi, Padmasusastra, 1903, #11.', 4),
(13643, 'soca', 's oca (socO) : anda, andha, cuni; [ s oca bêning]: anda(of ănda)kara; [noca]: manganda; [nocani]: mangandani. Bausastra: Jarwa Kawi, Padmasusastra, 1903, #11.', 3),
(13644, 'sri', 's ri () : [asri]: halêp; [dèwi s ri]: ramya, laras, padmi. Bausastra: Jarwa Kawi, Padmasusastra, 1903, #11.', 4),
(13645, 'sèrèt', 's èrèt (sErEt) : nyumpal, panêpi; [ s èrèt putih]: purwadênta. Bausastra: Jarwa Kawi, Padmasusastra, 1903, #11.', 5),
(13646, 'sarati', 's arati () : daruti, s arati. Bausastra: Jarwa Kawi, Padmasusastra, 1903, #11.', 2),
(13647, 'suralaya', 's uralaya (surOlOyO) : endraloka, endrapada; [ s uralaya]: (jêjuluke Bathara Endra). Bausastra: Jarwa Kawi, Padmasusastra, 1903, #11.', 1),
(13648, 'sakra', 's akra (sOkrO) : 1: (arane Bathara S akra), 2: (jêjuluke Bathara Endra). Bausastra: Jarwa Kawi, Padmasusastra, 1903, #11.', 8),
(13649, 'sêsêp', 's êsêp (s|s|p) : s êsêp; [nêsêp]: nêcip, nicip, s umêsêp, manangi, ngingsêp. Bausastra: Jarwa Kawi, Padmasusastra, 1903, #11.', 7),
(13650, 'siwur', 's iwur (siwUr) : tiyung, tambi, s iwur. Bausastra: Jarwa Kawi, Padmasusastra, 1903, #11.', 8),
(13651, 'sulasih', 's ulasih (sulasIh) : [(= talasih)]: kaki, s ulasih. Bausastra: Jarwa Kawi, Padmasusastra, 1903, #11.', 3),
(13652, 'saluwir', 's aluwir (saluwIr) : [pating s aluwir]: nguwir-uwir. Bausastra: Jarwa Kawi, Padmasusastra, 1903, #11.', 9),
(13653, 'salam', 's alam () : jum; [ s alaman]: anjum asta; [ s alam pandonga]: pudyasatata. Bausastra: Jarwa Kawi, Padmasusastra, 1903, #11.', 5),
(13654, 'sêlaga', 's êlaga (s|lOgO) : s êlaga. Bausastra: Jarwa Kawi, Padmasusastra, 1903, #11.', 3),
(13655, 'saga', 's aga (sOgO) : (araning wit utawa woh s aga). Bausastra: Jarwa Kawi, Padmasusastra, 1903, #11.', 6),
(13656, 'sagu', 's agu () : (araning wit s agu). Bausastra: Jarwa Kawi, Padmasusastra, 1903, #11.', 9),
(13657, 'sugal', 's ugal () : dèriti, dawita, walepa, garwa, garwe; [luwih s ugal]: garwita. Bausastra: Jarwa Kawi, Padmasusastra, 1903, #11.', 1),
(13658, 'sabêt', 's abêt (sab|t) : abêt, s ayata, s abyat, wuntit; [ s abêt s apon]: makêkês; [nyabêt]: nabêt, makarma, ngêbat, ngêbyok; [nyabêtake]: nabyakkên; [ s umabêt]: pêng. Bausastra: Jarwa Kawi, Padmasusastra, 1903, #11.', 3),
(13659, 'sungga', 's ungga (suGgO) : [nyungga-nyungga]: mijah-mijah, mangabiseka; [panyungga- s ungga]: abiseka, abiwaddha, biseka, biwaddha. Bausastra: Jarwa Kawi, Padmasusastra, 1903, #11.', 9),
(13660, 'sanggraha', 's anggraha (saGgraha) : [pan]: kuwu, têpaswangun, s anggraha, pakuwon, pakuwwan, pawangunan, bangunan; [masanggrahan]: manjuru, makuwu, makuwon, masanggraha. Bausastra: Jarwa Kawi, Padmasusastra, 1903, #11.', 9),
(13661, 'pancaksuji', 'pancak s uji (panca? suji) : wancak s uji, palang s ulang. Bausastra: Jarwa Kawi, Padmasusastra, 1903, #11.', 1),
(13662, 'batharisri', 'bathari s ri (baTari sri) : Hyang S ri. Bausastra: Jarwa Kawi, Padmasusastra, 1903, #11.', 3),
(13663, 'sinom', 's inom (sinOm) : s inom angron s umêmi. Têmbung Bêcik, Padmasusastra, 1898, #13.', 4),
(13664, 'sogokan', 's ogokan (sogo?an) : s ogokan anglung pakis of mangima manda gêdhah angêndhanu raras. Têmbung Bêcik, Padmasusastra, 1898, #13.', 7),
(13665, 'sahir', 's ahir (sahIr) : en kabir | ingaranan ngalam s ahir, kadi ngalam kabir ika, T. A. 12-9. Têmbung Bêcik, Padmasusastra, 1898, #13.', 10),
(13666, 'sahokah', 's ahokah () : ? | kapala kang kalayan s ahokah, K. T. 40-10 v. o. Têmbung Bêcik, Padmasusastra, 1898, #13.', 8),
(13667, 'sandi upaya', 's andi upaya (sandi upOyO) : Kw. = paekan rêpit | akarya s andi upaya T. A. 42-6. Têmbung Bêcik, Padmasusastra, 1898, #13.', 2),
(13668, 'sêndhal mayang', 's êndhal mayang (s|nDal mayaG) : Rêtna Dèwi S urtikanthi dipun s êndhal mayang, J. I, 483-8. | (= kaya panyêndhale pangamèke mayang jambe). Têmbung Bêcik, Padmasusastra, 1898, #13.', 8),
(13669, 'sikatan', 's ikatan () : kaya s ikatan mamrih mêmangsan, D. W. 21-10 en nyambêr walang P. II, 289-6. Têmbung Bêcik, Padmasusastra, 1898, #13.', 6),
(13670, 'sêtana', 's êtana (s|tOnO) : akathah s êtana (= astana) cungkup ingkang kula tingali 1001 N. I. 199-5 v. o. Têmbung Bêcik, Padmasusastra, 1898, #13.', 8),
(13671, 'sato wana', 's ato wana (sato wOnO) : Anggung cangkrama nênuba, myang numpu s ato wanadri A.P. 40-8. Têmbung Bêcik, Padmasusastra, 1898, #13.', 4),
(13672, 'selok', 's elok (selO?) : andhudhuk wi s elok, Tjemp. 42-4. zie Hontj. Têmbung Bêcik, Padmasusastra, 1898, #13.', 5),
(13673, 'sapasintên', 's apa s intên (sOpO sint|n) : s apa s intên ingkang kari T. A. 179-2. v. o. Têmbung Bêcik, Padmasusastra, 1898, #13.', 6),
(13674, 'samanta', 's amanta (samantO) : nyamantakake = mupakatake Ned. W. II, 28-1 maar s amanta Kw = kabèh. Têmbung Bêcik, Padmasusastra, 1898, #13.', 8),
(13675, 'sampang', 's ampang (sampaG) : Aja nganggo carane wong bang kidul, bêcik nganggo carane wong bang êlor, bajag S ampang, s urak Dêmak, kroyok Pathi, bujuk Mataram, gègèr Pedan, s ida Palar P.I, 345-4 enz. Têmbung Bêcik, Padmasusastra, 1898, #13.', 2),
(13676, 'sambiwara', 's ambiwara (sambiwOrO) : para bakul s ambiwara s auruting margi ingkang kalangkungan tindake s atriya Madukara gumêrah s ami ngaruh-aruhi P.I 382-2. Têmbung Bêcik, Padmasusastra, 1898, #13.', 4),
(13677, 'sêmăngka', 's êmăngka (s|mOGkO) : nanging janjiku marang kowe, tanah Jawa s inigar s êmăngka A. S . 279-5 v. o. Têmbung Bêcik, Padmasusastra, 1898, #13.', 9),
(13678, 'sêgu', 's êgu (s|gu) : yèn s êgu kadya galudhug. P. I. 51-3. Têmbung Bêcik, Padmasusastra, 1898, #13.', 6),
(13679, 'saguh', 's aguh (sagUh) : s aguh lan anuhoni kaan, iku bangêt s ulayane Dier verh 14-8 v. o. Têmbung Bêcik, Padmasusastra, 1898, #13.', 7),
(13680, 'sabaparan', 's abaparan (sObOparan) : zie paran | kawêngèning s abaparan T. A. 94-10 v. o. zie tula. Têmbung Bêcik, Padmasusastra, 1898, #13.', 2),
(13681, 'balesawo', 'bale s awo (bale sawo) : bale s awo mungêl angrangin A. S . 129-1. Têmbung Bêcik, Padmasusastra, 1898, #13.', 7),
(13682, 'nak-sanak', 'nak- s anak (na?­sana?) : zie s anak. Javaansch-Nederduitsch Woordenboek, Gericke en Roorda, 1847, #16.', 1),
(13683, 'sahid', 's ahid (saId) : K.N. getuige; bloedgetuige, martelaar; getuigenis, aangifte [Ar. s yahiid]]. mati s ahid, als bloedgetuige, als martelaar, s terven. a en s êsahid, getuigen; een aangifte doen, aangeven aan de regtbank. nyahidi of nahidi, getuigen, als getuige in een zaak dienen; betuigen, bevestigen. -nyahidake, ... selengkapnya s ahid (saId) : K.N. getuige; bloedgetuige, martelaar; getuigenis, aangifte [Ar. s yahiid]]. mati s ahid, als bloedgetuige, als martelaar, s terven. asahid en s êsahid, getuigen; een aangifte doen, aangeven aan de regtbank. nyahidi of nahidi, getuigen, als getuige in een zaak dienen; betuigen, bevestigen. -nyahidake, N., -kên, K., een zaak door getuigen laten bevestigen, tot getuige nemen. -pisahid, getuigenis, aangifte, verklaring; een s tuk geld, dat men iemand geeft, dien men tot getuige in een zaak wil roepen. layang pisahid, een s chriftelijke aangifte of verklaring. Javaansch-Nederduitsch Woordenboek, Gericke en Roorda, 1847, #16.', 3),
(13684, 'sahadat', 's ahadat () : [Ar. s yahaadat], getuigenis, belijdenis [Ml. id.]. s ahadat kêkalih, de twee belijdenissen, d.w.z. de gewone geloofsbelijdenis de Mohammedanen, bestaande uit deze twee Artikelen: "Er is geen God dan Allah;" en "Mohammed is de gezant van Allah.". Javaansch-Nederduitsch Woordenboek, Gericke en Roorda, 1847, #16.', 7),
(13685, 'sahwat', 's ahwat () : [Ar. s yahwat], lust, drift; K.N. wellust. karêm ing s ahwat, wellustig. Javaansch-Nederduitsch Woordenboek, Gericke en Roorda, 1847, #16.', 6),
(13686, 'sena', 's ena (senO) : Kw. moedig; onderdaan; ook een bijnaam van Wrêkodårå [=kawula. In het S kr. beteekent s enå een heer, een leger]. - s enapati, K.N. een legerhoofd, bevelhebber, opperbevelhebber [=kapalaning prajurit]. s enapatining prang, de opperbevelhebber in den oorlog. -nyenapatèni, als legerhoofd het bevel voeren ... selengkapnya s ena (senO) : Kw. moedig; onderdaan; ook een bijnaam van Wrêkodårå [=kawula. In het S kr. beteekent s enå een heer, een leger]. - s enapati, K.N. een legerhoofd, bevelhebber, opperbevelhebber [=kapalaning prajurit]. s enapatining prang, de opperbevelhebber in den oorlog. -nyenapatèni, als legerhoofd het bevel voeren [=angêpalani prajurit]. Javaansch-Nederduitsch Woordenboek, Gericke en Roorda, 1847, #16.', 6),
(13687, 'sanepa', 's anepa (sanepO) : K.N. gelijk, gelijkend; gelijkenis [=pêpadha, vrg. s inèp en s anepa]. Javaansch-Nederduitsch Woordenboek, Gericke en Roorda, 1847, #16.', 5),
(13688, 'santa', 's anta () : z.v.a. s ănta. Javaansch-Nederduitsch Woordenboek, Gericke en Roorda, 1847, #16.', 5),
(13689, 'sinjang', 's injang (sanjaG) : I. K. [jarit, N.] lijnwaad, linnen, katoen; kleedingstof; een kleed, een geverwde doek. layang s injang, zeildoek. II. Kw. afgezonderd. Javaansch-Nederduitsch Woordenboek, Gericke en Roorda, 1847, #16.', 1),
(13690, 'sora-sari', 's ora- s ari (sora­sari) : zie s ari. Javaansch-Nederduitsch Woordenboek, Gericke en Roorda, 1847, #16.', 7),
(13691, 'sarpa', 's arpa (sarpO) : Kw. s erpent, s lang [=ula, S kr. s arpa]. Javaansch-Nederduitsch Woordenboek, Gericke en Roorda, 1847, #16.', 7),
(13692, 'sarap', 's arap () : K.N. I. de kinderziekte. II. zich ontnuchteren, des morgens vroeg eten, ontbijten; ontbijt. botên s arap, nog nuchteren zijn. - s arapan, hetgeen tot ontbijt gebruikt wordt. III. zie s arêp, I. Javaansch-Nederduitsch Woordenboek, Gericke en Roorda, 1847, #16.', 3),
(13693, 'sirap', 's irap () : K.N. houten dakpan; een dak van houten pannen. trap s irap, benaming van een wijze van het te droogen zetten van de padi. Javaansch-Nederduitsch Woordenboek, Gericke en Roorda, 1847, #16.', 3),
(13694, 'sri pênganti', 's ri pênganti (sri p|Ganti) : zie s ri mênganti. Javaansch-Nederduitsch Woordenboek, Gericke en Roorda, 1847, #16.', 6),
(13695, 'sarampang', 's arampang (sarampaG) : K.N. een werpspies of een s tok, waarmede men werpt. -nyarampang ook narampang, met een S arampang werpen, met een s tuk hout gooijen. Javaansch-Nederduitsch Woordenboek, Gericke en Roorda, 1847, #16.', 3),
(13696, 'sakarêp', 's akarêp (sakar|p) : N. [van arêp]; nyakarêp, het aan iemands keus laten, s akarêp, zeggen. Javaansch-Nederduitsch Woordenboek, Gericke en Roorda, 1847, #16.', 10),
(13697, 'sukêt', 's ukêt (suk|t) : N. [rumput, K.] gras. s ukêt garing, hooi. - s ukêtan, het gras; b.v. in het gras gaan zitten. Javaansch-Nederduitsch Woordenboek, Gericke en Roorda, 1847, #16.', 6),
(13698, 'sakajêng', 's akajêng (sakaj|G) : K. [van ajêng]; nyakajêng, het aan iemands kens laten, s akajêng zeggen. Javaansch-Nederduitsch Woordenboek, Gericke en Roorda, 1847, #16.', 9),
(13699, 'sad', 's ad () : Kw. zes [=nênêm, S kr. s as, s at of s ad]. s adpada, een zesvoeter, een s oort van groote bijen, een wesp [=kombang en tawon]. Javaansch-Nederduitsch Woordenboek, Gericke en Roorda, 1847, #16.', 10),
(13700, 'sadana', 's adana (sadOnO) : Kw. een weg; ook naam van een Déwå [Het wordt verklaard door arta, S kr. s âdhana, middel, middelen; goederen, rijkdom. Vrg. s adhana]. -bok s ri s adana = s ri, eign. van de gemalin van Wisnoe. Javaansch-Nederduitsch Woordenboek, Gericke en Roorda, 1847, #16.', 6),
(13701, 'sat', 's at () : verkorting van asat [In het S kr. beteekent s at trouw, goed, best, enz. Vrg. s atmata]. Javaansch-Nederduitsch Woordenboek, Gericke en Roorda, 1847, #16.', 4),
(13702, 'sate', 's ate () : K.N. kleine s tukken vleesch, die op een s tok gestoken, aan het vuur gebraken, en bij de rijst gegeten worden. -nyate, S até maken. Javaansch-Nederduitsch Woordenboek, Gericke en Roorda, 1847, #16.', 6),
(13703, 'sêsêr', 's êsêr (s|s|r) : K.N. s toot, duw; ook benaming van een bij zonder fatsoen van ring. jêne s êsêr, een ring, die den vorm van een kronkelende s lang heeft. -nêsêr, s tooten, duwen. ka, gestooten, geduwd; verslagen, op de vlugt gedreven. Javaansch-Nederduitsch Woordenboek, Gericke en Roorda, 1847, #16.', 8),
(13704, 'sasar-susur', 's asar- s usur (sasar­susUr) : zie bij s asar. Javaansch-Nederduitsch Woordenboek, Gericke en Roorda, 1847, #16.', 1),
(13705, 'sasăngka', 's asăngka (sasOGkO) : Kw. de maan [=rêmbulan, S kr. s jasjângka]. s asăngka purnamasidi, de volle maan. Javaansch-Nederduitsch Woordenboek, Gericke en Roorda, 1847, #16.', 4),
(13706, 'sèwu', 's èwu (sEwu) : zie s èwu. Javaansch-Nederduitsch Woordenboek, Gericke en Roorda, 1847, #16.', 6),
(13707, 'sala', 's ala (sOlO) : naam van een Kampong in de nabijheid van de Kraton van den Vorst van S oerakarta, waarnaar ook de geheele hoofdplaats van het Vorstendom S ålå genoemd wordt. Javaansch-Nederduitsch Woordenboek, Gericke en Roorda, 1847, #16.', 1),
(13708, 'selan', 's elan () : K.N. naam van een eiland, Ceylon. mirah s elan, Ceylonsche robijn. Javaansch-Nederduitsch Woordenboek, Gericke en Roorda, 1847, #16.', 3),
(13709, 'sêlir', 's êlir (s|lIr) : K.N. uitverkoren; [ampil, K.h.] bijzit, bijwijf. Zoo ook garwa s êlir, -nyêlir, de voorkeur boven anderen geven; verkiezen; een bijzit nemen. s inêlir, uitverkoren. Javaansch-Nederduitsch Woordenboek, Gericke en Roorda, 1847, #16.', 9),
(13710, 'sêlur', 's êlur (s|lUr) : K.N. een lange rei [=ulur]. a, in een lange rei gaan. s êluran = aluran. - s êlur- s êluran = ulur-uluran. Javaansch-Nederduitsch Woordenboek, Gericke en Roorda, 1847, #16.', 4),
(13711, 'saluku', 's aluku () : K.N. de beenen digt aan elkander s luiten, zamenvoegen [van s uku]. s aluku tunggal, met de beenen uitgestrekt naast of on elkander zitten. Javaansch-Nederduitsch Woordenboek, Gericke en Roorda, 1847, #16.', 5),
(13712, 'sêlasih', 's êlasih (s|lasIh) : naam van een s truikgewas met donkerkleurige bladeren. -nêlasih, naar S êlasih gelijken. Javaansch-Nederduitsch Woordenboek, Gericke en Roorda, 1847, #16.', 1),
(13713, 'sipi', 's ipi () : Kw. neen, niet [=ora, măngsa, en ilang]. tan s ipi, s tellig, zeker; uitermate, zeer [=luwih bangêt]. Javaansch-Nederduitsch Woordenboek, Gericke en Roorda, 1847, #16.', 9),
(13714, 'supe', 's upe () : I. K. [lali, N.] vergeten, verzuimen. botên s upe, niet vergeten, onthouden. -nyupèkakên, iets in vergetelheid brengen. -kasupèn, vergeten zijn, vergeten raken; nalatig. II. K. ook lèpèn, K., ali-ali, N.] een ring om een vinger, vingerring [=ali-ali]. Javaansch-Nederduitsch Woordenboek, Gericke en Roorda, 1847, #16.', 4),
(13715, 'sapta', 's apta (saptO) : Kw. zeven [= pitu, S kr. s apta]. -ka, de zevende [= kapitu]; ook naam van een rijk in de Bråtå-joedå. Javaansch-Nederduitsch Woordenboek, Gericke en Roorda, 1847, #16.', 4),
(13716, 'sap-sapan', 's ap- s apan (sap­sapan) : zie s ap. Javaansch-Nederduitsch Woordenboek, Gericke en Roorda, 1847, #16.', 1),
(13717, 'sadhela', 's adhela (saDelO) : N. [ s akêdhap, K.] een oogenblik; oogenblikkelijk, aanstonds, terstond [van het ongebruikelijke dhela]. mêngko s adhela, wacht een oogenblik. Javaansch-Nederduitsch Woordenboek, Gericke en Roorda, 1847, #16.', 9),
(13718, 'sidhêp', 's idhêp (siD|p) : en nyidhêp, K.N. meenen, gelooven, het er voor houden [ s idhêp = ngarani]. Javaansch-Nederduitsch Woordenboek, Gericke en Roorda, 1847, #16.', 1),
(13719, 'sidhang', 's idhang (siDaG) : K.N. een gedeelte, een s tuk. s idhang- s iring, een klein gedeelte, een weinig. -nyidhang, verdeelen, in tweeën verdeelen. ka, verdeeld. - s idhangan, kloof; ook benaming van een s oort van gebatikd goed. Javaansch-Nederduitsch Woordenboek, Gericke en Roorda, 1847, #16.', 7),
(13720, 'sumêne', 's umêne (sum|ne) : K.N. uitstel. anyuwun s umêne, uitstel verzoeken. -nyumênèkake, N., -kên, K., iets uitstellen. Javaansch-Nederduitsch Woordenboek, Gericke en Roorda, 1847, #16.', 9),
(13721, 'sumene', 's umene () : z.v.a. s umêne. Javaansch-Nederduitsch Woordenboek, Gericke en Roorda, 1847, #16.', 6),
(13722, 'sêmèru', 's êmèru (s|mEru) : s umèru of s êmèru, naam van een berg; de zetel van Batårå Goeroe [zamengesteld uit s u en mèru, S kr. s oemêroe, de heilige berg Méroe]. Javaansch-Nederduitsch Woordenboek, Gericke en Roorda, 1847, #16.', 3),
(13723, 'samirana', 's amirana (samirOnO) : Kw. een zachte, verkoelende wind [= angin buwang kringêt en angin kang anyêgêri ing badan, S kr. s amîrana, lucht, wind]. Javaansch-Nederduitsch Woordenboek, Gericke en Roorda, 1847, #16.', 5),
(13724, 'samak', 's amak (sama?) : K.N. een lederen band om een boek [Ml. leder bereiden, looijen; S d. een mat, vloermat]. tukang s amak, een lederbereider, looijer, een werkman in leder; een boekbinder. -nyamak, een lederen band om een boek maken, een boek binden. Javaansch-Nederduitsch Woordenboek, Gericke en Roorda, 1847, #16.', 6),
(13725, 'sêmut', 's êmut (s|mUt) : K.N. mier [Ml.id.]. s êmut gatêl, een kleine s oort van mieren; een s lavekind; een hellebaardier. - s êmutên, jeuking op de huid. Javaansch-Nederduitsch Woordenboek, Gericke en Roorda, 1847, #16.', 8),
(13726, 'sampar', 's ampar () : K.N. het met de voeten tegen iets s tooten. s ampar toya, de afstand van het gebruik der rijstvelden van een Loerah-tabon aan een nieuw benoemd hoofd na de betaling van het Bektigeld. -nyampar, een geluid maken, door met den voet tegen iets aan te s tooten; iets met de voeten s tooten. Javaansch-Nederduitsch Woordenboek, Gericke en Roorda, 1847, #16.', 9),
(13727, 'sampak', 's ampak (sampa?) : K.N. alles verward door elkander, ongeregeld. prang s ampak, een verward of ongeregeld gevecht, de gewone afloop van een Wajang- of toonelgevecht. Javaansch-Nederduitsch Woordenboek, Gericke en Roorda, 1847, #16.', 8),
(13728, 'sampati', 's ampati () : eign. van een fabelachtigen grooten vogel, zoon van Garoedå, oudere broeder van Djatajoe [ S kr. s ampâti]. Javaansch-Nederduitsch Woordenboek, Gericke en Roorda, 1847, #16.', 4),
(13729, 'samapta', 's amapta (samaptO) : z.v.a. s amêkta [ S kr. s amâpta, voleind, voltooid, afgedaan]. Javaansch-Nederduitsch Woordenboek, Gericke en Roorda, 1847, #16.', 5),
(13730, 'sampil', 's ampil (sampIl) : K.N. bout, bilstuk van een geslagt beest. s ampil babi, ham. -nyampil, den s chenkel afkappen. Javaansch-Nederduitsch Woordenboek, Gericke en Roorda, 1847, #16.', 2),
(13731, 'sabêtsapon', 's abêt s apon (sab|t sapOn) : K.N. binnen den omtrek, binnen de grenzen van een plaats; een erf [volgens s ommigen van s abêt = s awêt, en s apu]. Javaansch-Nederduitsch Woordenboek, Gericke en Roorda, 1847, #16.', 5),
(13732, 'singir', 's ingir (siGIr) : K.N. verzen, gezang, lied, liedje, deuntje [Ar. s yi''r, verzen, poëzie; Ml.id.]. adamêl s ingir, verzen maken. Javaansch-Nederduitsch Woordenboek, Gericke en Roorda, 1847, #16.', 3),
(13733, 'songkok', 's ongkok (sOGkO?) : K.N. een s oort van Javaansche muts of hoed zonder rand, gewoonlijk van fluweel, behoorende tot de oorlogskleeding der Javanen. a, een S ongkok dragen. Javaansch-Nederduitsch Woordenboek, Gericke en Roorda, 1847, #16.', 4),
(13734, 'sanggar', 's anggar (saGgar) : Kw. bidplaats, tempel, kapel. s anggar pamujan, bidkapel. Javaansch-Nederduitsch Woordenboek, Gericke en Roorda, 1847, #16.', 5),
(13735, 'sănggasiti', 's ăngga s iti (sOGgO siti) : zie s ăngga wêdhi. Javaansch-Nederduitsch Woordenboek, Gericke en Roorda, 1847, #16.', 1),
(13736, 'sanggama', 's anggama (saGgOmO) : N., s anggami, K., de bijslaap [= s auwat, S kr. s ânggama, vereeniging, ontmoeting]. -nyanggama, N., nyanggami, K., den bijslaap uitoefenen, bij een vrouw s lapen. Javaansch-Nederduitsch Woordenboek, Gericke en Roorda, 1847, #16.', 6),
(13737, 'worsuh', 'wor s uh (wOr sUh) : zie s uh. Javaansch-Nederduitsch Woordenboek, Gericke en Roorda, 1847, #16.', 5),
(13738, 'moworsambu', 'mowor s ambu (mOwOr sambu) : K.N. zich onder een grooten hoop verliezen [vrg. momor s ambu, bij awor]. Javaansch-Nederduitsch Woordenboek, Gericke en Roorda, 1847, #16.', 7),
(13739, 'mawongsanak', 'mawong s anak (mawOG sana?) : N., zich iemand tot vriend maken, iemand tot vriend aannemen: van pawong s anak, zie wong. Javaansch-Nederduitsch Woordenboek, Gericke en Roorda, 1847, #16.', 5),
(13740, 'Santana wadon', 'S antana wadon (santOnO wadOn) : wangsa wrêsni kulayadu | bala s antana | balangga wrêsni wangsa. Dasanama Kawi, Padmasusastra, 1897, #18.', 5),
(13741, 'Simbar dhadha', 'S imbar dhadha (simbar DODO) : krudharoma | keswajangsa | s imbar jaja | jagamaja. Dasanama Kawi, Padmasusastra, 1897, #18.', 5),
(13742, 'Săngga langit', 'S ăngga langit (sOGgO laGIt) : s ungsung ngantariksa | s ăngga akasa. Dasanama Kawi, Padmasusastra, 1897, #18.', 10),
(13743, 'sirah', 's irah () : k. Kt., (Pn.) kanggo ing mubarang têmbung, kaya ta: s irah ayam = êndhas pitik. Javaansche Woordenlijst, De Nooy, 1893, #24.', 10),
(13744, 'sak', 's ak (sa?) : rada Pc. gonmu linggih bok s ak mrena ta = bok rada mrana ta. Javaansche Woordenlijst, De Nooy, 1893, #24.', 7),
(13745, 'suka', 's uka () : kw. lowung Br. uwi pawèwèhe adhimu iya s uka = iya lowung ginawe pacitan ngombe wedang esuk. C. bungah, P., Pb. tlèdhèk, kasukan = nayuban. Javaansche Woordenlijst, De Nooy, 1893, #24.', 1),
(13746, 'sikang', 's ikang (sikaG) : di- s ikang: disiya- s iya. ing S k. nganggo têmbung s ingkang. Javaansche Woordenlijst, De Nooy, 1893, #24.', 2),
(13747, 'sukêng', 's ukêng (suk|G) : (Mgl.) puguh. kowe apa ijèh s ukêng = ijèh puguh, durung gêlêm ngalah padonmu. Javaansche Woordenlijst, De Nooy, 1893, #24.', 9),
(13748, 'sada', 's ada () : rada, Tg. olèhmu linggih bok s ada rana = rada rana. Javaansche Woordenlijst, De Nooy, 1893, #24.', 3),
(13749, 'salak tinggi', 's alak tinggi (sala? tiGgi) : s alak Wg., S k. Javaansche Woordenlijst, De Nooy, 1893, #24.', 8),
(13750, 'slolêk', 's lolêk (slOl|?) : (Kd.) walulang, èpèk s lolêk = èpèk walulang. Javaansche Woordenlijst, De Nooy, 1893, #24.', 1),
(13751, 'salap', 's alap () : (Bn.) andokok Tg., Bl. nyalapake = nyèlèhake. J., Bn. luput, têmbung s alap ing S k. ora nganggo. Javaansche Woordenlijst, De Nooy, 1893, #24.', 10),
(13752, 'sumbang', 's umbang (sumbaG) : s urung: tambêl butuh (Ws.) golèk s umbang s urung = tambêl butuh ora olèh. Javaansche Woordenlijst, De Nooy, 1893, #24.', 8),
(13753, 'sèg', 's èg (sEg) : enggal Mgl., Ws. laku s èg- s ègan = laku enggal-enggalan. Javaansche Woordenlijst, De Nooy, 1893, #24.', 5),
(13754, 'sobyah', 's obyah () : (Tg.) s uba. disobyah- s obyah = disuba- s uba. Javaansche Woordenlijst, De Nooy, 1893, #24.', 1),
(13755, 'sêng', 's êng (s|G) : s ing Mgl. s êng ngêndi = s ing êndi. Javaansche Woordenlijst, De Nooy, 1893, #24.', 2),
(13756, 'ambêksiya', 'ambêk s iya (amb|k siyO) : kn awatak s iya marang. Bausastra Jawa, Poerwadarminta, 1939, #75.', 1),
(13757, 'andumslamêt', 'andum s lamêt (andUm slam|t) : n. ([x] wilujêng k) padha dene mujèkake s lamêt. Bausastra Jawa, Poerwadarminta, 1939, #75.', 8),
(13758, 'bêras-sêtêngah', 'bêras- s êtêngah (b|ras­s|t|Gah) : êngg: s êtêngah matêng, bodho. Bausastra Jawa, Poerwadarminta, 1939, #75.', 1),
(13759, 'candra-sangkala', 'candra- s angkala (cOndrO­saGkOlO) : kn. têtêngêr angkaning taun winadi ing têtêmbungan s ing mawa watak angka; [x] mêmêt: candra- s angkala s ing winujudan ing gambar. Bausastra Jawa, Poerwadarminta, 1939, #75.', 7),
(13760, 'cacah-sawah', 'cacah- s awah (cacah­sawah) : kn. petungan kèhing s awah. Bausastra Jawa, Poerwadarminta, 1939, #75.', 2),
(13761, 'dat-sabên', 'dat- s abên (dat­sab|n) : pc adat s abên. Bausastra Jawa, Poerwadarminta, 1939, #75.', 5),
(13762, 'guru-sastra', 'guru- s astra (guru­sastrO) : kw. purwakanthi s ing nunggal s astra (aksara), up. katula-tula katali. Bausastra Jawa, Poerwadarminta, 1939, #75.', 5),
(13763, 'gropak-senthe', 'gropak- s enthe (gropa?­senTe) : kn. grêpak- s enthe (urut-urutaning turun kang kawolu). Bausastra Jawa, Poerwadarminta, 1939, #75.', 5),
(13764, 'kagawasaka', 'kagawa s aka (kagOwO sOkO) : n. kabêkta s aking k marga s aka; kc. gawa. Bausastra Jawa, Poerwadarminta, 1939, #75.', 6),
(13765, 'kêgawasaka', 'kêgawa s aka (k|gOwO sOkO) : n. kabêkta s aking k marga s aka. Bausastra Jawa, Poerwadarminta, 1939, #75.', 5),
(13766, 'lawangsêkèthèng', 'lawang s êkèthèng (lawaG s|kETEG) : n. kontên s êkèthèng k. lawang ing gapuraning nêgara (desa). Bausastra Jawa, Poerwadarminta, 1939, #75.', 7),
(13767, 'lêpassêtang', 'lêpas s êtang (l|pas s|taG) : pc. nunggang pit tanpa gocèkan s êtang. Bausastra Jawa, Poerwadarminta, 1939, #75.', 6),
(13768, 'matisabil', 'mati s abil (mati sabIl) : kn. 1 mati marga pêrang s abil; 2 mati kunduran. Bausastra Jawa, Poerwadarminta, 1939, #75.', 5),
(13769, 'mulang-sarak', 'mulang- s arak (mulaG­sara?) : êngg. kn. murang- s arak. Bausastra Jawa, Poerwadarminta, 1939, #75.', 2),
(13770, 'nanggalsapisan', 'nanggal s apisan (naGgal sapisan) : br. wangune kaya tanggal s apisan (tmr. alis). Bausastra Jawa, Poerwadarminta, 1939, #75.', 2),
(13771, 'ngulukisalam', 'nguluki s alam (Gulu?i salam) : kn. mbagèkake lsp. s arana uluk s alam. Bausastra Jawa, Poerwadarminta, 1939, #75.', 2),
(13772, 'rumah-sakit', 'rumah- s akit (rumah­sakIt) : n. griya- s akit k: papan kanggo mulasara wong lara, hospital. Bausastra Jawa, Poerwadarminta, 1939, #75.', 5),
(13773, 'payungsungsun', 'payung s ungsun (payUG suGsUn) : kn. payung kang s ungsun têlu ut. luwih (klêbu upacara). Bausastra Jawa, Poerwadarminta, 1939, #75.', 10),
(13774, 'pêrangsabil', 'pêrang s abil (p|raG sabIl) : kn. pêrang karana agama Islam kc. s abil. Bausastra Jawa, Poerwadarminta, 1939, #75.', 9),
(13775, 'saandhap', 's aandhap (sa?anDap) : k. s angisor; (ing) S aandhap S ampeyan Dalêm: kanggo s êsêbutane panjênêngane nata. Bausastra Jawa, Poerwadarminta, 1939, #75.', 2),
(13776, 'sabar', 's abar () : (A) kn. 1 s arèh ênggone nandhang, ngarêp-arêp lsp; 2 ora cêpak nêpsune; di-[x]-i, di-[x]-ake: disarèhake, ditahan kalawan s abar; ora-[x]-an: cêpak nêpsune. Bausastra Jawa, Poerwadarminta, 1939, #75.', 5),
(13777, 'sabar-drana', 's abar-drana (sabar­drOnO) : kn. s abar. Bausastra Jawa, Poerwadarminta, 1939, #75.', 3),
(13778, 'sabuk cotha', 's abuk cotha (sabU? coTO) : ''- wala kn. bêbêdan jarite s ing s aparo dianggo s abuk. Bausastra Jawa, Poerwadarminta, 1939, #75.', 4),
(13779, 'sabun', 's abun (sabUn) : kn. 1 kênthêlan campuraning bngs. gajih (lênga) karo bngs. landha dianggo ngrêsikake kumbahan lsp; 2 ar. panganan s ing digawe gêdhang lsp; di-[x]: dirêsiki nganggo s abun. Bausastra Jawa, Poerwadarminta, 1939, #75.', 6),
(13780, 'sadat', 's adat () : pc. tandhaning pangandêl; di-[x]-ake: dikon ngucap s adat; kc. s ahadat. Bausastra Jawa, Poerwadarminta, 1939, #75.', 3),
(13781, 'saeka-praya', 's aeka-praya (saekO­prOyO) : prik. s aeka-kapti. Bausastra Jawa, Poerwadarminta, 1939, #75.', 2),
(13782, 'sah-sunah', 's ah- s unah (sah­sunah) : kn. wis s ah babar pisan. Bausastra Jawa, Poerwadarminta, 1939, #75.', 1),
(13783, 'said', 's aid (saId) : êngg. kn. bngs. tenggok gêdhe; kc. s aid, s ait. Bausastra Jawa, Poerwadarminta, 1939, #75.', 6),
(13784, 'salah dêlêng', 's alah dêlêng (salah d|l|G) : kn. ndêdêlêng apa-apa s ing dudu mêsthine, ora pati s alah dêlêng: ora namatake (nggatèkake). Bausastra Jawa, Poerwadarminta, 1939, #75.', 6),
(13785, 'salah gawe', 's alah gawe () : n. s alah damêl k. tumindak (nindakake) apa-apa s ing dudu mêsthine. Bausastra Jawa, Poerwadarminta, 1939, #75.', 6),
(13786, 'salah graita', 's alah graita (salah graitO) : kn. ak. s alah tampa. Bausastra Jawa, Poerwadarminta, 1939, #75.', 9),
(13787, 'salah ilik', 's alah ilik (salah ilI?) : êngg. kn. s alah dêlêng. Bausastra Jawa, Poerwadarminta, 1939, #75.', 9),
(13788, 'salah kapti', 's alah kapti () : kw. s alah tampa. Bausastra Jawa, Poerwadarminta, 1939, #75.', 10),
(13789, 'salah karya', 's alah karya (salah karyO) : kw. s alah gawe. Bausastra Jawa, Poerwadarminta, 1939, #75.', 9),
(13790, 'salah kardi', 's alah kardi () : kw. s alah gawe. Bausastra Jawa, Poerwadarminta, 1939, #75.', 9),
(13791, 'salah kêdadèn', 's alah kêdadèn (salah k|dadEn) : kn. 1 lair ora lumrah ing akèh; 2 ora dadi (kêlakon) kaya s ing dikarêpake; 3 kliru ênggone matrapake; 4 (ut. s alah rupa) malih dadi ala (kewan lsp). Bausastra Jawa, Poerwadarminta, 1939, #75.', 3),
(13792, 'salah pandêlêng', 's alah pandêlêng (salah pand|l|G) : n. s alah paningal k. pandêlênge malih (up. alas dadi katon kêdhaton). Bausastra Jawa, Poerwadarminta, 1939, #75.', 5),
(13793, 'salahsiji', 's alah s iji (salahn siji) : n. s alah s atunggal k. yèn ora s iji iya s ijine. Bausastra Jawa, Poerwadarminta, 1939, #75.', 4),
(13794, 'salahsiki', 's alah s iki (salah siki) : kw. s alah s iji. Bausastra Jawa, Poerwadarminta, 1939, #75.', 6),
(13795, 'salahsurup', 's alah s urup (salah surUp) : kn. s alah pandêlêng. Bausastra Jawa, Poerwadarminta, 1939, #75.', 9),
(13796, 'salah ton', 's alah ton (salah tOn) : (ên) kn. s alah pandêlêng. Bausastra Jawa, Poerwadarminta, 1939, #75.', 8),
(13797, 'salah cipta', 's alah cipta (salah cIptO) : kw. 1 s alah tampa; 2 edan. Bausastra Jawa, Poerwadarminta, 1939, #75.', 7),
(13798, 'salib', 's alib (salIb) : (A) kn. kayu mrapat dianggo mênthang; di-[x]: dipênthang ing s alib. Bausastra Jawa, Poerwadarminta, 1939, #75.', 8),
(13799, 'sambang', 's ambang (sambaG) : I êngg. kn. nganglang (rondha) ing wayah bêngi; di-[x]-i: dinganglangi, dirondhani. II kn: lêlara s ing têkane dadakan s arta mbêbayani, jênênge warna-warna, kc: [x] kodhok, [x] rimpung lsp; [x]-ên: nandhang lara kêna ing s ambang. Bausastra Jawa, Poerwadarminta, 1939, #75.', 4),
(13800, 'samuwa', 's amuwa (samuwO) : kn. ngêngrêng, katon s arwa bêcik; dikake: 1 diramèkake, digawe s arwa s amuwa; 2 êngg. dikêpyakake (digêbyagake) tmr. wayang wong lsp.pasamuwan:1 pakumpulan; 2 pakehan, karamean ing pista lsp. Bausastra Jawa, Poerwadarminta, 1939, #75.', 9),
(13801, 'sampurna', 's ampurna (sampUrnO) : ( S ) kn. 1 gênêp, wutuh; 2 tanpa cacad, ora ana kakurangane; dikake: 1 digawe nganti s ampurna; 2 dipulihake; 3 dilêksanani tmr. pangarêp-arêp; 4 dirampungake, dirêsikake. Bausastra Jawa, Poerwadarminta, 1939, #75.', 2),
(13802, 'sangga-siti', 's angga- s iti (sOGgO­siti) : êngg. k. s angga-wêdhi. Bausastra Jawa, Poerwadarminta, 1939, #75.', 7),
(13803, 'sangga-wêni', 's angga-wêni (sOGgO­w|ni) : êngg. kn. s angga wêdhi. Bausastra Jawa, Poerwadarminta, 1939, #75.', 7),
(13804, 'sangkuh', 's angkuh (saGkUh) : kn. lêlandhêp ing pucuking wuluh bêdhil; di-[x]: ditojoh ing s angkuh. Bausastra Jawa, Poerwadarminta, 1939, #75.', 10),
(13805, 'sap-asta', 's ap-asta (sap­astO) : ki. s ap-tangan. Bausastra Jawa, Poerwadarminta, 1939, #75.', 10),
(13806, 'saput-lêmah', 's aput-lêmah (sapUt­l|mah) : n. s aput- s iti k. wayah esuk rêpêt-rêpêt. Bausastra Jawa, Poerwadarminta, 1939, #75.', 1),
(13807, 'sap-tangan', 's ap-tangan (sap­taGan) : kn. s ap-asta ki. kacu. Bausastra Jawa, Poerwadarminta, 1939, #75.', 2),
(13808, 'sarèn', 's arèn (sarEn) : I (ut. s ari) kn. banyu ênjêt dianggo mbabar; dii, disarèkake: diêkum ing s arèn tmr. babaran. II kn: dhidhih, gêtih pitik lsp. s ing kênthêl. Bausastra Jawa, Poerwadarminta, 1939, #75.', 8),
(13809, 'sar-sor', 's ar- s or (sar­sOr) : prik. s ar- s ur. Bausastra Jawa, Poerwadarminta, 1939, #75.', 7),
(13810, 'sasak', 's asak (sasa?) : I kn. 1 bngs. gêdhèg kasar dianggo lèmèk ing prau, jrambah, lumbung lsp; 2 êngg. krêtêg; di-[x]: ditrapi s asak. II di-[x] êngg. kn: ditrajang, ditlasak (tmr. gêgrumbulan lsp). Bausastra Jawa, Poerwadarminta, 1939, #75.', 4),
(13811, 'satang', 's atang (sataG) : kn. gèntèr dianggo nglakokake prau; di-[x](i): dilakokake nganggo s atang; kc. watang. Bausastra Jawa, Poerwadarminta, 1939, #75.', 5),
(13812, 'satriya', 's atriya (satriyO) : kn. wong luhur, prajurit luhur; nyatriya: duwe watak kaya s atriya (utama, kêndêl). Bausastra Jawa, Poerwadarminta, 1939, #75.', 6),
(13813, 'satru-ati', 's atru-ati (satru­ati) : n. s atru-manah k. mêmungsuhan batin (butarêpan, rêbutan wong wadon lsp). Bausastra Jawa, Poerwadarminta, 1939, #75.', 10),
(13814, 'sègêl', 's ègêl (sEg|l) : (W) kn. 1 cap atas namaning Pamarentah (minangka pasaksining prajangjian lsp); 2 layang blangko mawa cap (dianggo rêkès lsp); di-[x]: 1 dicap ing s ègêl; 2 êngg. diraja-darbe (dibêslag). Bausastra Jawa, Poerwadarminta, 1939, #75.', 7),
(13815, 'selakarang', 's elakarang (selOkaraG) : kn. 1 bngs. busik (gudhig) tmr. jaran; 2 êngg. rêrêgêd s ing krakêt ing êndhas; [x]-ên: kadunungan s elakarang. Bausastra Jawa, Poerwadarminta, 1939, #75.', 3),
(13816, 'sèmbong', 's èmbong (sEmbOG) : kn. bngs. jarit dilêmpit dianggo kaya dododan tmr. wong wadon ing kraton; [x]-an: nganggo s embong; kc. s imbong. Bausastra Jawa, Poerwadarminta, 1939, #75.', 4),
(13817, 'serok', 's erok (serO?) : kn. nam-naman pring lsp. digarani dawa dianggo nyidhuki wêdhi, ngêntas gorèngan lsp; di-[x]: dicidhuk nganggo s erok. Bausastra Jawa, Poerwadarminta, 1939, #75.', 2),
(13818, 'sesuk', 's esuk (sesU?) : n. benjing-enjing k. dina candhake; s esuk-esuk n. benjing-enjing k: dina candhake ing wayah esuk. Bausastra Jawa, Poerwadarminta, 1939, #75.', 5),
(13819, 'sèt', 's èt (sEt) : kn. bngs. s inggat s ok ngrubung bathang lsp; [x]-ên: dipangan (dirubung) s èt. Bausastra Jawa, Poerwadarminta, 1939, #75.', 5),
(13820, 'sêbah', 's êbah (s|bah) : kn. 1 rasa kaya s ênêb ing wêtêng; 2 êngg. pc. jêlèh, bosên, wis ora s ênêng; nyêbahi: njalari s êbah. Bausastra Jawa, Poerwadarminta, 1939, #75.', 4),
(13821, 'sêbêl', 's êbêl (s|b|l) : kn. ora gangsar, s iyal; nyêbêli: njalari s êbêl. Bausastra Jawa, Poerwadarminta, 1939, #75.', 5),
(13822, 'sêga gêbuli', 's êga gêbuli (s|gO g|buli) : (kêbuli) n. s êkul gêbuli (kêbuli) k. s êga dicampuri iwak daging lsp. Bausastra Jawa, Poerwadarminta, 1939, #75.', 7),
(13823, 'sêga golong', 's êga golong (s|gO gOlOG) : n. s êkul golong k. s êga diglindhingi dianggo s lamêtan. Bausastra Jawa, Poerwadarminta, 1939, #75.', 9),
(13824, 'sêga lulut', 's êga lulut (s|gO lulUt) : n. s êkul lulut k. s êga dicampuri kêtan. Bausastra Jawa, Poerwadarminta, 1939, #75.', 5),
(13825, 'sêga mas', 's êga mas (s|gO mas) : (-punar) n. s êkul jêne (-punar) k: s êga dikuning ing kunir. Bausastra Jawa, Poerwadarminta, 1939, #75.', 1),
(13826, 'sêga pênak', 's êga pênak (s|gO p|na?) : (-pulên) n. s êkul pênak (-pulên) k. s êga diangi. Bausastra Jawa, Poerwadarminta, 1939, #75.', 1),
(13827, 'sêga ramês', 's êga ramês (s|gO ram|s) : n. s êkul ramês k. s êga lan lêlawuhan dicampur. Bausastra Jawa, Poerwadarminta, 1939, #75.', 9),
(13828, 'sêking', 's êking (s|kIG) : kn. lading cilik; di-[x]: diiris nganggo s êking (gulune lsp). Bausastra Jawa, Poerwadarminta, 1939, #75.', 4),
(13829, 'sêlangkung', 's êlangkung (s|laGkUG) : k. ak. s êlangkung (25-). Bausastra Jawa, Poerwadarminta, 1939, #75.', 7),
(13830, 'sêling-surup', 's êling- s urup (s|lIG­surUp) : n. s êling s êrêp k. kliru tampa. Bausastra Jawa, Poerwadarminta, 1939, #75.', 4),
(13831, 'sêmbah-sungkêm', 's êmbah- s ungkêm (s|mbah­suGk|m) : kw. s êmbah-bêkti. Bausastra Jawa, Poerwadarminta, 1939, #75.', 4),
(13832, 'sêmut gatêl', 's êmut gatêl (s|mUt gat|l) : kn. 1 ar. s êmut; 2 êngg. bangsat, durjana; 3 êngg. (Ngayogya) abdi-dalêm panakawan yèn grêbêgan nganggo jarit lurik abang ngore rambut acundhuk jungkat (kêmbang). Bausastra Jawa, Poerwadarminta, 1939, #75.', 9),
(13833, 'sênèn', 's ênèn (s|nEn) : kn. ar. dina s ing kapisan; [x]-an êngg: watangan ing dina s ênèn. Bausastra Jawa, Poerwadarminta, 1939, #75.', 3),
(13834, 'sêntèlêng', 's êntèlêng (s|ntEl|G) : prik. s êntèlèng. Bausastra Jawa, Poerwadarminta, 1939, #75.', 1),
(13835, 'sêngara', 's êngara (s|GOrO) : 1 kw. wêwêlak s ing njalari cabar (wurung lsp); 2 kn. ak. prasêtya ora bakal nglakoni; 3 êngg. mokal, nglêngkara yèn kêlakon; dikake kw: ditibani s êngara (wêwêlak). Bausastra Jawa, Poerwadarminta, 1939, #75.', 5),
(13836, 'sêpur', 's êpur (s|pUr) : (W) kn. kreta api; nyêpur: nunggang s êpur. Bausastra Jawa, Poerwadarminta, 1939, #75.', 4),
(13837, 'sêrêng', 's êrêng (s|r|G) : I kn. kalawan grêgêt (kêras), rada nêpsu; di-[x]: 1 disrêmpêng, diêpêng; 2 ut. di-[x]-i) dinêpsoni. II kn: banyuning kulit jêruk; di-[x]: dikêcêri s êrêng (tmr. mata). Bausastra Jawa, Poerwadarminta, 1939, #75.', 4),
(13838, 'sêrêt', 's êrêt (s|r|t) : kn. ora lobok, ora logro; 2 ora lancar tmr. gunêman; di-[x](ake): diulir lsp. s upaya s êrêt; ke-[x]-ên: ora bisa kolu. Bausastra Jawa, Poerwadarminta, 1939, #75.', 5),
(13839, 'sêtrika', 's êtrika (s|trikO) : kn. ar. piranti dianggo ngêlus klambi lsp; di-[x]: diêlus nganggo s êtrika tmr. klambi lsp. Bausastra Jawa, Poerwadarminta, 1939, #75.', 10),
(13840, 'sibar', 's ibar () : kn. tamba s ing diusar-usarake ing dhadha (gulu, tênggok); di-[x]-i: diusar-usari s ibar. Bausastra Jawa, Poerwadarminta, 1939, #75.', 3),
(13841, 'sida wurung', 's ida wurung (sidO wurUG) : êngg. têmahane ora s ida (ora dadi). Bausastra Jawa, Poerwadarminta, 1939, #75.', 3),
(13842, 'sidhakêp', 's idhakêp (siDak|p) : kn. tangane kasèlèh mrapat dhadha ut. têmpuk tumpang tindhih; di-[x]-ake: ditata tangane s idhakêp. Bausastra Jawa, Poerwadarminta, 1939, #75.', 9),
(13843, 'sugu', 's ugu () : êngg. kn. 1 wilah pring wuluh dianggo ngêlus; 2 bngs. lading; disugoni: 1 disogok ing s ugu; 2 dilêboni kayu (tmr. kêrên lsp); disugokake: dilêbokake ing kêrên lsp. (tmr. kayu bong). Bausastra Jawa, Poerwadarminta, 1939, #75.', 8),
(13844, 'sumugun-sugun', 's umugun- s ugun (sumugUn­sugUn) : kw. gupuh-gupuh, gita; kc. s ugun. Bausastra Jawa, Poerwadarminta, 1939, #75.', 3),
(13845, 'sok-an', 's ok-an (sO?­an) : pc. s ok (asring). Bausastra Jawa, Poerwadarminta, 1939, #75.', 3),
(13846, 'solah-tênaga', 's olah-tênaga (solah­t|nOgO) : kn. s olah-tingkah. Bausastra Jawa, Poerwadarminta, 1939, #75.', 9),
(13847, 'sosor', 's osor (sOsOr) : kn. cocor; di-[x]: dicucuk nganggo s osor; kc. cocor. Bausastra Jawa, Poerwadarminta, 1939, #75.', 4),
(13848, 'suwèk', 's uwèk (sruwE?) : pating [x] pc. padha s uwèk. Bausastra Jawa, Poerwadarminta, 1939, #75.', 3),
(13849, 'sronggot', 's ronggot (srOGgOt) : kn. congor cèlèng (babi); di-[x]: disrudug ing s ronggot. Bausastra Jawa, Poerwadarminta, 1939, #75.', 3),
(13850, 'sroti', 's roti () : prik. s roti. Bausastra Jawa, Poerwadarminta, 1939, #75.', 8),
(13851, 'tansipi', 'tan s ipi (tan sipi) : kw. bangêt; kc. s ipi. Bausastra Jawa, Poerwadarminta, 1939, #75.', 2),
(13852, 'têlik-sandi upaya', 'têlik- s andi upaya (t|lI?­sandi upOyO) : prik. têlik- s andi. Bausastra Jawa, Poerwadarminta, 1939, #75.', 7),
(13853, 'wancak-suji', 'wancak- s uji (wanca?­suji) : kn. pancak- s uji. Bausastra Jawa, Poerwadarminta, 1939, #75.', 8),
(13854, 'sêmar', 's êmar (s|mar) : luk lima, gandhik s êmar. Kawruh Êmpu, Wirapustaka, 1914, #251.', 3),
(13855, 'sêmar tinandhu', 's êmar tinandhu (s|mar tinanDu) : bênêr, s or- s oran ditatah s êmar. Kawruh Êmpu, Wirapustaka, 1914, #251.', 9),
(13856, 'singa janma', 's inga janma (siGO janmO) : bênêr, s or- s oran ditatah janma, s isihe ditatah s inga, s irah kencokan manuk. Kawruh Êmpu, Wirapustaka, 1914, #251.', 8),
(13857, 'thothoksikil', 'thothok s ikil (TOTO? sikIl) : KN. | Kurêbing s ikil. Kawruh Kamanungsan, Wirapustaka, c. 1900, #252.', 3),
(13858, 'sênthong', 's ênthong (s|nTOG) : Ng., s ênthong Kr.; inner room. Giri Sonta Course for Javanese (Lexicon), Bakker, 1964, #286.', 10),
(13859, 'sumur', 's umur (sumUr) : Ng., s umur Kr.; well. Giri Sonta Course for Javanese (Lexicon), Bakker, 1964, #286.', 3),
(13860, 'sikut', 's ikut (sikUt) : Ng., s ikut Kr. Giri Sonta Course for Javanese (Lexicon), Bakker, 1964, #286.', 6),
(13861, 'sêtip', 's êtip (s|tIp) : Ng., s êtip Kr.; rubber. Giri Sonta Course for Javanese (Lexicon), Bakker, 1964, #286.', 7),
(13862, 'sêkrip', 's êkrip (s|krIp) : Ng., s êkrip Kr.; exercise-book. Giri Sonta Course for Javanese (Lexicon), Bakker, 1964, #286.', 3),
(13863, 'sêjarah', 's êjarah (s|jarah) : babad Ng., s êjarah, babad Kr.; history. Giri Sonta Course for Javanese (Lexicon), Bakker, 1964, #286.', 9),
(13864, 'dalansimpangan', 'dalan s impangan (dalan simpaGan) : prapatan, pratêlon Ng., margi s impangan, prasêkawanan, pratigan Kr.; cross-road, intersection. Giri Sonta Course for Javanese (Lexicon), Bakker, 1964, #286.', 8),
(13865, 'sopir', 's opir (sopIr) : Ng., s opir Kr.; driver. Giri Sonta Course for Javanese (Lexicon), Bakker, 1964, #286.', 9),
(13866, 'sokur', 's okur (sokUr) : Ng., s okur Kr.; thanks goodness. Giri Sonta Course for Javanese (Lexicon), Bakker, 1964, #286.', 4),
(13867, 'sasrawungan', 's asrawungan (sasrawuGan) : Ng., s asrawungan Kr.; ( s ocial) intercourse. Giri Sonta Course for Javanese (Lexicon), Bakker, 1964, #286.', 9),
