(14695, 'tumênggung', 't umênggung : t umênggung, bopati, nayaka, wadana, manggala, prawara, pratiwa, pradhara. Dasanamajarwa, Dirjaatmaja, 1913, #1168.', 5),
(14696, 'tandhaning dumadi', 't andhaning dumadi : t êgêsipun pratandhaning t itah, dene t andhaning gêsang saking latu, witing latu saking srêngenge. Dasanamajarwa, Dirjaatmaja, 1913, #1168.', 5),
(14697, 'tawontutur', 't awon t utur [Wngs] : t awon wisma. Sandi-Asma lan Wangsalan, Dirdjosiswojo, 1957, #1257.', 5),
(14698, 'taman soka', 't aman soka [Wngs] : t aman lêngka. Sandi-Asma lan Wangsalan, Dirdjosiswojo, 1957, #1257.', 1),
(14699, 'tantra', 't antra (tOntrO) : t ăntra: bala. Kawi - Jarwa, Dirjasupraba, 1931, #1263.', 1),
(14700, 'tampêr', 't ampêr (tamp|r) : wêdhi. uyah t ampêr: uyah wêdhi. Kawi - Jarwa, Dirjasupraba, 1931, #1263.', 8),
(14701, 'tiarda', 't iarda (tiyardO) : bangêt. răga- t iarda: lara bangêt. Kawi - Jarwa, Dirjasupraba, 1931, #1263.', 5),
